-- ===== selection-tracking-documents-local.sql =====
-- LOCAL PRO ONLY. Round 10 (2026-11-15), Documents and Selections (Houzz Pro parity rows 45, 62).
--  * Change order printable copy (row 45): owner read of one change with its number in the job, lines
--    (description and amount only: the internal cost/markup is never printed), totals and status.
--    Quotes print from the existing pro_private_estimate_read (no new SQL).
--  * Selections (row 62): order/delivery tracking per selection item (not ordered → ordered → delivered
--    → installed, only after the customer approved an option), internal unit cost per option and the
--    resulting margin (owner only; never in customer reads or the printed sheet), bulk tracking update,
--    customer bulk approval of several items in one transaction (each through the existing customer
--    writer, same receipts/history), and the printable selections sheet read.
-- Patterns: RLS on, service_role only, security invoker, CAS 40001, idempotent actionId receipts,
-- immutable history, CRC cents, Costa Rica dates. Nothing is sent; no third party is called.
begin;
create table if not exists public.pro_work_selection_tracking(
 owner_id uuid not null references public.profiles(id) on delete cascade,item_id uuid not null,work_id text not null,
 status text not null check(status in('not_ordered','ordered','delivered','installed')),ordered_on date,delivered_on date,
 supplier_ref text not null default '' check(length(supplier_ref)<=80),revision integer not null check(revision>0),updated_at timestamptz not null default clock_timestamp(),
 primary key(owner_id,item_id),foreign key(owner_id,item_id) references public.pro_work_selection_items(owner_id,id) on delete cascade,
 check(ordered_on is null or ordered_on between date'2000-01-01' and date'2100-12-31'),check(delivered_on is null or delivered_on between date'2000-01-01' and date'2100-12-31'),
 check(status='not_ordered' or ordered_on is not null),check(status not in('delivered','installed') or delivered_on is not null),check(delivered_on is null or ordered_on is not null and delivered_on>=ordered_on));
create table if not exists public.pro_work_selection_option_costs(
 owner_id uuid not null references public.profiles(id) on delete cascade,option_id uuid not null,unit_cost_cents bigint check(unit_cost_cents between 0 and 10000000000),
 revision integer not null check(revision>0),updated_at timestamptz not null default clock_timestamp(),
 primary key(owner_id,option_id),foreign key(owner_id,option_id) references public.pro_work_selection_options(owner_id,id) on delete cascade);
create table if not exists public.pro_work_selection_tracking_history(
 owner_id uuid not null references public.profiles(id) on delete cascade,action_id uuid not null,target_kind text not null check(target_kind in('tracking','cost')),target_id uuid not null,
 work_id text not null,before_value jsonb,after_value jsonb not null,at timestamptz not null default clock_timestamp(),primary key(owner_id,action_id,target_id));
create table if not exists public.pro_work_selection_tracking_actions(
 owner_id uuid not null references public.profiles(id) on delete cascade,action_id uuid not null,input jsonb not null,result jsonb not null,
 at timestamptz not null default clock_timestamp(),primary key(owner_id,action_id));
create table if not exists public.pro_work_selection_bulk_actions(
 actor_id uuid not null references public.profiles(id) on delete cascade,action_id uuid not null,input jsonb not null,result jsonb not null,
 at timestamptz not null default clock_timestamp(),primary key(actor_id,action_id));
do $$declare t text;begin
 foreach t in array array['pro_work_selection_tracking_history','pro_work_selection_tracking_actions','pro_work_selection_bulk_actions'] loop
  execute format('drop trigger if exists %I on public.%I',t||'_immutable',t);
  execute format('create trigger %I before update or delete on public.%I for each row when (pg_trigger_depth()=0) execute function public.pro_round10_immutable()',t||'_immutable',t);
 end loop;
 foreach t in array array['pro_work_selection_tracking','pro_work_selection_option_costs','pro_work_selection_tracking_history','pro_work_selection_tracking_actions','pro_work_selection_bulk_actions'] loop
  execute format('alter table public.%I enable row level security',t);execute format('revoke all on public.%I from public,anon,authenticated',t);execute format('grant all on public.%I to service_role',t);
 end loop;
end $$;

create or replace function public.pro_work_selection_tracking_json(p_owner uuid,p_item uuid) returns jsonb language sql stable security invoker set search_path=public,pg_temp as $$
 select jsonb_build_object('status',coalesce(t.status,'not_ordered'),'orderedOn',t.ordered_on,'deliveredOn',t.delivered_on,'supplierRef',coalesce(t.supplier_ref,''),'revision',coalesce(t.revision,0))
 from(select 1) one left join public.pro_work_selection_tracking t on t.owner_id=p_owner and t.item_id=p_item $$;

-- Owner tracker: items with approval, tracking, options with internal cost and margin; totals in cents.
create or replace function public.pro_work_selection_tracking_read(p_owner uuid,p_work text) returns jsonb language plpgsql stable security invoker set search_path=public,pg_temp as $$
declare items jsonb;
begin
 if not coalesce(public.pro_private_work_tools_enabled(p_owner),false) then raise exception 'Forbidden' using errcode='42501';end if;
 if p_work is null or length(p_work) not between 1 and 160 then raise exception 'Invalid work' using errcode='22023';end if;
 if not exists(select 1 from public.pro_work where user_id=p_owner and id=p_work) then return null;end if;
 select coalesce(jsonb_agg(jsonb_build_object('itemId',i.id,'name',i.name,'areaName',a.name,'state',public.pro_work_selection_state(i),'revision',i.revision,
   'approvedOptionId',i.approved_option_id,'recommendedOptionId',i.recommended_option_id,'dueDate',i.due_date,'tracking',public.pro_work_selection_tracking_json(p_owner,i.id),
   'options',coalesce((select jsonb_agg(jsonb_build_object('optionId',o.id,'name',o.name,'quantity',o.quantity,'unitCents',o.unit_cents,'totalCents',o.total_cents,
     'unitCostCents',c.unit_cost_cents,'costRevision',coalesce(c.revision,0),'costCents',case when c.unit_cost_cents is null then null else round(o.quantity*c.unit_cost_cents)::bigint end,
     'marginCents',case when c.unit_cost_cents is null then null else o.total_cents-round(o.quantity*c.unit_cost_cents)::bigint end,
     'marginBps',case when c.unit_cost_cents is null or o.total_cents=0 then null else round((o.total_cents-round(o.quantity*c.unit_cost_cents))*10000.0/o.total_cents)::integer end) order by o.position)
    from public.pro_work_selection_options o left join public.pro_work_selection_option_costs c on c.owner_id=o.owner_id and c.option_id=o.id where o.owner_id=i.owner_id and o.item_id=i.id and not o.archived),'[]'::jsonb)) order by a.position,i.position),'[]'::jsonb)
 into items from public.pro_work_selection_items i join public.pro_work_selection_areas a on a.owner_id=i.owner_id and a.id=i.area_id
 where i.owner_id=p_owner and i.work_id=p_work and not i.archived and not a.archived;
 return jsonb_build_object('workId',p_work,'today',public.pro_work_selection_today(),'items',items,
  'totals',(select jsonb_build_object('approved',count(*) filter(where x->>'state'='approved'),
    'approvedPriceCents',coalesce(sum((o->>'totalCents')::bigint) filter(where o is not null),0),
    'approvedCostCents',coalesce(sum((o->>'costCents')::bigint),0),'approvedWithoutCost',count(*) filter(where o is not null and o->'costCents'='null'::jsonb),
    'marginCents',coalesce(sum((o->>'marginCents')::bigint),0),
    'notOrdered',count(*) filter(where x->>'state'='approved' and x->'tracking'->>'status'='not_ordered'),'ordered',count(*) filter(where x->'tracking'->>'status'='ordered'),
    'delivered',count(*) filter(where x->'tracking'->>'status' in('delivered','installed')))
   from jsonb_array_elements(items) x left join lateral(select y from jsonb_array_elements(x->'options') y where y->>'optionId'=x->>'approvedOptionId') ao(o) on true));
end $$;

create or replace function public.pro_work_selection_tracking_mutate(p_owner uuid,p_input jsonb) returns jsonb language plpgsql security invoker set search_path=public,pg_temp as $$
declare act text;keys text[];aid uuid;wid text;receipt public.pro_work_selection_tracking_actions;answer jsonb;ref jsonb;item public.pro_work_selection_items;tr public.pro_work_selection_tracking;
 opt public.pro_work_selection_options;cost public.pro_work_selection_option_costs;before_json jsonb;v_status text;v_ordered date;v_delivered date;v_ref text;today date:=public.pro_work_selection_today();n integer:=0;
begin
 if not coalesce(public.pro_private_work_tools_enabled(p_owner),false) then raise exception 'Forbidden' using errcode='42501';end if;
 if jsonb_typeof(p_input) is distinct from 'object' then raise exception 'Invalid tracking action' using errcode='22023';end if;
 act:=p_input->>'action';select array_agg(x order by x) into keys from jsonb_object_keys(p_input) x;
 if keys is distinct from (case act when 'tracking_set' then array['action','actionId','deliveredOn','itemId','orderedOn','revision','status','supplierRef','workId'] when 'bulk_track' then array['action','actionId','items','status','workId'] when 'cost_set' then array['action','actionId','optionId','revision','unitCostCents','workId'] end)
  or jsonb_typeof(p_input->'workId') is distinct from 'string' then raise exception 'Unexpected tracking fields' using errcode='22023';end if;
 begin aid:=(p_input->>'actionId')::uuid;exception when others then raise exception 'Invalid action id' using errcode='22023';end;
 wid:=p_input->>'workId';if not exists(select 1 from public.pro_work where user_id=p_owner and id=wid) then raise exception 'Forbidden' using errcode='42501';end if;
 perform pg_advisory_xact_lock(hashtextextended('pro-selection-tracking:'||p_owner::text||':'||aid::text,0));
 select * into receipt from public.pro_work_selection_tracking_actions where owner_id=p_owner and action_id=aid;
 if found then if receipt.input is distinct from p_input then raise exception 'Action id reused' using errcode='22023';end if;return receipt.result||jsonb_build_object('replayed',true);end if;
 perform pg_advisory_xact_lock(hashtextextended('pro-work-selection:'||p_owner::text||':'||wid,0));
 if act='cost_set' then
  begin select * into opt from public.pro_work_selection_options where owner_id=p_owner and work_id=wid and id=(p_input->>'optionId')::uuid and not archived;exception when others then raise exception 'Invalid option' using errcode='22023';end;
  if opt.id is null then raise exception 'Option unavailable' using errcode='P0002';end if;
  if jsonb_typeof(p_input->'unitCostCents') not in('number','null') or p_input->'unitCostCents'<>'null'::jsonb and((p_input->>'unitCostCents')!~'^[0-9]{1,11}$' or(p_input->>'unitCostCents')::bigint>10000000000) or jsonb_typeof(p_input->'revision') is distinct from 'number' then raise exception 'Invalid cost' using errcode='22023';end if;
  select * into cost from public.pro_work_selection_option_costs where owner_id=p_owner and option_id=opt.id for update;
  if coalesce(cost.revision,0)<>(p_input->>'revision')::integer then raise exception 'Cost changed' using errcode='40001';end if;
  before_json:=jsonb_build_object('unitCostCents',cost.unit_cost_cents);
  insert into public.pro_work_selection_option_costs(owner_id,option_id,unit_cost_cents,revision) values(p_owner,opt.id,(p_input->>'unitCostCents')::bigint,1)
   on conflict(owner_id,option_id) do update set unit_cost_cents=excluded.unit_cost_cents,revision=public.pro_work_selection_option_costs.revision+1,updated_at=clock_timestamp() returning * into cost;
  insert into public.pro_work_selection_tracking_history(owner_id,action_id,target_kind,target_id,work_id,before_value,after_value) values(p_owner,aid,'cost',opt.id,wid,before_json,jsonb_build_object('unitCostCents',cost.unit_cost_cents));
  answer:=jsonb_build_object('action',act,'optionId',opt.id,'unitCostCents',cost.unit_cost_cents,'revision',cost.revision);
 else
  v_status:=p_input->>'status';if v_status not in('not_ordered','ordered','delivered','installed') then raise exception 'Invalid status' using errcode='22023';end if;
  if act='bulk_track' then
   if jsonb_typeof(p_input->'items') is distinct from 'array' or jsonb_array_length(p_input->'items') not between 1 and 100 then raise exception 'Invalid items' using errcode='22023';end if;
  end if;
  for ref in select case when act='bulk_track' then value else jsonb_build_object('itemId',p_input->'itemId','revision',p_input->'revision') end from jsonb_array_elements(case when act='bulk_track' then p_input->'items' else '[0]'::jsonb end) loop
   if jsonb_typeof(ref->'revision') is distinct from 'number' or not coalesce(ref->>'revision'~'^[0-9]{1,10}$',false) then raise exception 'Invalid revision' using errcode='22023';end if;
   begin select * into item from public.pro_work_selection_items where owner_id=p_owner and work_id=wid and id=(ref->>'itemId')::uuid and not archived for update;exception when others then raise exception 'Invalid item' using errcode='22023';end;
   if item.id is null then raise exception 'Item unavailable' using errcode='P0002';end if;
   if v_status<>'not_ordered' and item.status<>'approved' then raise exception 'Only approved selections can be ordered' using errcode='22023';end if;
   select * into tr from public.pro_work_selection_tracking where owner_id=p_owner and item_id=item.id for update;
   if coalesce(tr.revision,0)<>(ref->>'revision')::integer then raise exception 'Tracking changed' using errcode='40001';end if;
   if act='tracking_set' then
    if jsonb_typeof(p_input->'orderedOn') not in('string','null') or jsonb_typeof(p_input->'deliveredOn') not in('string','null') or jsonb_typeof(p_input->'supplierRef') is distinct from 'string' or length(btrim(p_input->>'supplierRef'))>80 then raise exception 'Invalid tracking' using errcode='22023';end if;
    begin v_ordered:=(p_input->>'orderedOn')::date;v_delivered:=(p_input->>'deliveredOn')::date;exception when others then raise exception 'Invalid date' using errcode='22023';end;
    v_ref:=btrim(p_input->>'supplierRef');
   else
    v_ordered:=case when v_status='not_ordered' then null else coalesce(tr.ordered_on,today) end;v_delivered:=case when v_status in('delivered','installed') then coalesce(tr.delivered_on,today) end;v_ref:=coalesce(tr.supplier_ref,'');
   end if;
   if v_status='not_ordered' then v_ordered:=null;v_delivered:=null;elsif v_status='ordered' then v_delivered:=null;end if;
   before_json:=public.pro_work_selection_tracking_json(p_owner,item.id);
   begin
    insert into public.pro_work_selection_tracking(owner_id,item_id,work_id,status,ordered_on,delivered_on,supplier_ref,revision) values(p_owner,item.id,wid,v_status,v_ordered,v_delivered,v_ref,1)
     on conflict(owner_id,item_id) do update set status=excluded.status,ordered_on=excluded.ordered_on,delivered_on=excluded.delivered_on,supplier_ref=excluded.supplier_ref,revision=public.pro_work_selection_tracking.revision+1,updated_at=clock_timestamp();
   exception when check_violation then raise exception 'Invalid tracking dates' using errcode='22023';end;
   insert into public.pro_work_selection_tracking_history(owner_id,action_id,target_kind,target_id,work_id,before_value,after_value) values(p_owner,aid,'tracking',item.id,wid,before_json,public.pro_work_selection_tracking_json(p_owner,item.id));
   n:=n+1;
  end loop;
  answer:=jsonb_build_object('action',act,'updated',n,'status',v_status);
 end if;
 insert into public.pro_work_selection_tracking_actions(owner_id,action_id,input,result) values(p_owner,aid,p_input,answer);
 return answer;
end $$;

-- Customer: approve several items at once (each through the existing customer writer; all or nothing).
create or replace function public.pro_work_selections_client_bulk(p_actor uuid,p_input jsonb) returns jsonb language plpgsql security invoker set search_path=public,pg_temp as $$
declare aid uuid;receipt public.pro_work_selection_bulk_actions;ref jsonb;keys text[];n integer:=0;answer jsonb;
begin
 if not exists(select 1 from public.profiles where id=p_actor and not coalesce(is_disabled,false)) then raise exception 'Forbidden' using errcode='42501';end if;
 select array_agg(x order by x) into keys from jsonb_object_keys(p_input) x;
 if keys is distinct from array['action','actionId','items','requestId'] or p_input->>'action'<>'approve_many' or jsonb_typeof(p_input->'items') is distinct from 'array' or jsonb_array_length(p_input->'items') not between 1 and 50 or jsonb_typeof(p_input->'requestId') is distinct from 'string' then raise exception 'Invalid bulk approval' using errcode='22023';end if;
 begin aid:=(p_input->>'actionId')::uuid;exception when others then raise exception 'Invalid action id' using errcode='22023';end;
 perform pg_advisory_xact_lock(hashtextextended('pro-selection-bulk:'||p_actor::text||':'||aid::text,0));
 select * into receipt from public.pro_work_selection_bulk_actions where actor_id=p_actor and action_id=aid;
 if found then if receipt.input is distinct from p_input then raise exception 'Action id reused' using errcode='22023';end if;return receipt.result||jsonb_build_object('replayed',true);end if;
 for ref in select value from jsonb_array_elements(p_input->'items') loop
  select array_agg(x order by x) into keys from jsonb_object_keys(ref) x;
  if keys is distinct from array['id','optionId','revision'] then raise exception 'Invalid bulk item' using errcode='22023';end if;
  perform public.pro_work_selections_client_mutate(p_actor,jsonb_build_object('action','approve','actionId',public.pro_lead_import_uuid('pro-selection-bulk:'||aid::text||':'||(ref->>'id')),'requestId',p_input->>'requestId','id',ref->>'id','optionId',ref->>'optionId','revision',ref->'revision'));
  n:=n+1;
 end loop;
 answer:=jsonb_build_object('action','approve_many','approved',n);
 insert into public.pro_work_selection_bulk_actions(actor_id,action_id,input,result) values(p_actor,aid,p_input,answer);
 return answer;
end $$;

-- Printable selections sheet (customer-facing content: no internal cost or margin).
create or replace function public.pro_work_selection_print_read(p_owner uuid,p_work text) returns jsonb language plpgsql stable security invoker set search_path=public,pg_temp as $$
declare w public.pro_work;
begin
 if not coalesce(public.pro_private_work_tools_enabled(p_owner),false) then raise exception 'Forbidden' using errcode='42501';end if;
 select * into w from public.pro_work where user_id=p_owner and id=p_work;if not found then return null;end if;
 return jsonb_build_object('workId',w.id,'service',w.service,'client',coalesce(w.client,''),'today',public.pro_work_selection_today(),
  'areas',coalesce((select jsonb_agg(jsonb_build_object('name',a.name,'items',x.items) order by a.position) from public.pro_work_selection_areas a
   join lateral(select jsonb_agg(jsonb_build_object('name',i.name,'state',public.pro_work_selection_state(i),'dueDate',i.due_date,'approvedAt',i.approved_at,'tracking',public.pro_work_selection_tracking_json(p_owner,i.id)->>'status',
     'option',(select jsonb_build_object('name',o.name,'brand',o.brand,'quantity',o.quantity,'unitCents',o.unit_cents,'totalCents',o.total_cents,'approved',o.id=i.approved_option_id) from public.pro_work_selection_options o where o.owner_id=i.owner_id and o.id=coalesce(i.approved_option_id,i.recommended_option_id)),
     'optionCount',(select count(*) from public.pro_work_selection_options o where o.owner_id=i.owner_id and o.item_id=i.id and not o.archived)) order by i.position) items
    from public.pro_work_selection_items i where i.owner_id=a.owner_id and i.area_id=a.id and not i.archived) x on x.items is not null
   where a.owner_id=p_owner and a.work_id=p_work and not a.archived),'[]'::jsonb));
end $$;

-- Printable change order (owner): number in the job, customer lines (no internal cost/markup), totals.
create or replace function public.pro_work_change_print_read(p_owner uuid,p_change uuid) returns jsonb language plpgsql stable security invoker set search_path=public,pg_temp as $$
declare c public.pro_work_changes;w public.pro_work;
begin
 if not coalesce(public.pro_work_changes_enabled(p_owner),false) then raise exception 'Forbidden' using errcode='42501';end if;
 select * into c from public.pro_work_changes where owner_id=p_owner and id=p_change;if not found then return null;end if;
 select * into w from public.pro_work where user_id=p_owner and id=c.work_id;
 return jsonb_build_object('id',c.id,'number',(select count(*) from public.pro_work_changes x where x.owner_id=p_owner and x.work_id=c.work_id and x.position<=c.position),
  'workId',c.work_id,'service',coalesce(w.service,''),'client',coalesce(w.client,''),'reason',c.reason,'status',c.status,'recordedBy',c.recorded_by,'acceptanceNote',c.acceptance_note,
  'lines',(select jsonb_agg(jsonb_build_object('description',l->>'description','amountCents',(l->>'amountCents')::bigint) order by n) from jsonb_array_elements(c.lines) with ordinality y(l,n)),
  'baseCents',c.base_cents,'deltaCents',c.delta_cents,'totalCents',c.total_cents,'scheduleDays',c.schedule_days,'createdAt',c.created_at,'updatedAt',c.updated_at);
end $$;

do $$declare f record;begin
 for f in select p.oid::regprocedure sig from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='public' and p.proname in(
  'pro_work_selection_tracking_json','pro_work_selection_tracking_read','pro_work_selection_tracking_mutate','pro_work_selections_client_bulk','pro_work_selection_print_read','pro_work_change_print_read') loop
  execute format('revoke all on function %s from public,anon,authenticated',f.sig);execute format('grant execute on function %s to service_role',f.sig);end loop;
end $$;
commit;
notify pgrst,'reload schema';

-- ===== finance-identity-reports-local.sql =====
-- LOCAL PRO ONLY. Round 11 (2026-11-15), Finance (Houzz Pro parity rows 23, 42-44, 50-52, 54, 55, 57).
--  * Company fiscal identity (row 43): pro_company_fiscal_identity fills every EMPTY issuer field from the
--    company record (business name ▸ account name, contact e-mail, phone formatted «+506 XXXX-XXXX»,
--    address). Fix 13 (privacy): only the professional/company contact data; never the login e-mail, the
--    account's personal cédula or personal phone from profiles (the cédula is typed in issuer settings). Saved issuer settings always win field by field. Used by
--    every new invoice draft (direct, «Bill from job», installment, from source) through
--    pro_invoice_configured_save, and by the draft form defaults (/api/pro/invoice-drafts). No invoice is
--    emitted, signed or sent.
--  * Reports (rows 23, 55): pro_reports_read keeps its keys and now (a) ages each invoice by the SAME open
--    balance as the invoice draft (total − payments − credit notes applied, pro_credit_draft_balance) and
--    (b) gives each job the result WITH committed purchase orders plus its basis, so «Costs and committed»
--    and «Result» compare the same things (before: the result left out the committed column it was shown
--    next to). pro_reports_finance_read adds: receivables aging per customer, payments received (with
--    reversed payments and refunds apart), IVA (sales tax) summary per rate from the invoice lines, all in
--    CRC cents and Costa Rica dates.
--  * Purchase orders from the job (rows 51, 62): pro_purchase_order_sources lists the accepted quote lines
--    (with the owner's internal unit cost when known), the approved selection options (with their internal
--    cost) and the budget codes with planned amounts, plus what is already ordered of each, so the PO form
--    is prefilled; the order is still created by the existing PO writer (numbering, CAS, receipts, history).
--  * Payment plan reminders (row 57): new in-app event «payment_plan_due» (an installment of an active plan
--    due within the person's «due soon» days), owner only; overdue installments keep «invoice_overdue».
--    Nothing is sent: e-mail stays a never-sent draft when the person chose it.
-- Patterns: RLS on, service_role only, security invoker, CRC cents, Costa Rica dates. Read-only except the
-- notification sync (idempotent per source key) and the draft creation it wraps.
begin;

-- ===== Company fiscal identity =====
create or replace function public.pro_company_phone(p_value text) returns text language sql immutable security invoker set search_path=public,pg_temp as $$
 select case when x.d ~ '^[0-9]{8}$' then '+506 '||left(x.d,4)||'-'||right(x.d,4)
  when x.d ~ '^506[0-9]{8}$' then '+506 '||substr(x.d,4,4)||'-'||right(x.d,4)
  else left(btrim(coalesce(p_value,'')),30) end
 from (select regexp_replace(regexp_replace(regexp_replace(btrim(coalesce(p_value,'')),'[[:space:]().-]','','g'),'^\+',''),'^00','') d) x $$;

create or replace function public.pro_company_fiscal_identity(p_owner uuid) returns jsonb language plpgsql stable security invoker set search_path=public,pg_temp as $$
declare cfg jsonb;saved jsonb;pro record;prof record;d_name text;d_id text;d_type text;d_email text;d_phone text;d_addr text;issuer jsonb;src jsonb;
begin
 if p_owner is null then raise exception 'Invalid owner' using errcode='22023';end if;
 cfg:=public.pro_invoice_issuer_read(p_owner);saved:=coalesce(cfg->'issuer','{}'::jsonb);
 select p.business_name,p.contact_email,p.call_phone,p.whatsapp,p.formatted_address,p.address into pro from public.professionals p where p.profile_id=p_owner order by p.id limit 1;
 select f.full_name into prof from public.profiles f where f.id=p_owner;
 d_name:=left(coalesce(nullif(btrim(pro.business_name),''),nullif(btrim(prof.full_name),''),''),160);
 -- Fix 13: no identification is taken from the login profile; it comes only from saved issuer settings.
 d_id:='';d_type:='';
 d_email:=lower(btrim(coalesce(nullif(btrim(pro.contact_email),''),'')));
 if d_email !~ '^[^@[:space:]]+@[^@[:space:]]+\.[^@[:space:]]+$' or length(d_email)>254 then d_email:='';end if;
 d_phone:=public.pro_company_phone(coalesce(nullif(btrim(pro.call_phone),''),nullif(btrim(pro.whatsapp),''),''));
 d_addr:=left(btrim(coalesce(nullif(btrim(pro.formatted_address),''),pro.address,'')),500);
 issuer:=jsonb_build_object(
  'issuerName',coalesce(nullif(btrim(saved->>'issuerName'),''),d_name),
  'issuerIdType',case when coalesce(btrim(saved->>'issuerId'),'')<>'' then coalesce(saved->>'issuerIdType','') else d_type end,
  'issuerId',coalesce(nullif(btrim(saved->>'issuerId'),''),d_id),
  'issuerEmail',coalesce(nullif(btrim(saved->>'issuerEmail'),''),d_email),
  'issuerPhone',coalesce(nullif(btrim(saved->>'issuerPhone'),''),d_phone),
  'issuerAddress',coalesce(nullif(btrim(saved->>'issuerAddress'),''),d_addr),
  'issuerActivity',coalesce(saved->>'issuerActivity',''));
 src:=(select jsonb_object_agg(k,case when coalesce(btrim(saved->>k),'')<>'' then 'saved' when coalesce(issuer->>k,'')<>'' then 'company' else 'missing' end)
  from unnest(array['issuerName','issuerId','issuerEmail','issuerPhone','issuerAddress','issuerActivity']) k);
 return jsonb_build_object('revision',coalesce((cfg->>'revision')::integer,0),'issuer',issuer,'sources',src,
  'complete',issuer->>'issuerName'<>'' and issuer->>'issuerId'<>'' and (issuer->>'issuerEmail'<>'' or issuer->>'issuerPhone'<>''));
end $$;

-- Supersedes invoice-document-settings-local.sql: without saved issuer settings a NEW draft (direct, from
-- a source, «Bill from job», installment) starts with the whole company identity, not only its name.
create or replace function public.pro_invoice_configured_save(p_user uuid,p_input jsonb) returns uuid
language plpgsql security invoker set search_path=public,pg_temp as $$
declare existing uuid;saved uuid;config jsonb;defaults jsonb;d pro_invoice_drafts;prep jsonb;v_today text;
begin
 perform pg_advisory_xact_lock(hashtextextended(p_user::text,0));
 if p_input->>'action'='create_direct' then select id into existing from pro_invoice_drafts where user_id=p_user and id=(p_input->>'requestId')::uuid;
 elsif p_input->>'action'='create' then existing:=(pro_invoice_source(p_user,p_input->>'kind',p_input->>'sourceId')->>'existingId')::uuid;end if;
 saved:=pro_invoice_direct_save(p_user,p_input);
 if existing is not null or p_input->>'action' not in ('create','create_direct') or p_input ? 'preparation' then return saved;end if;
 config:=pro_invoice_issuer_read(p_user);defaults:=pro_invoice_document_settings_read(p_user);
 -- Round 11: every empty issuer field comes from the company (saved settings win field by field).
 config:=jsonb_set(config,'{issuer}',public.pro_company_fiscal_identity(p_user)->'issuer');
 if (config->>'revision')::integer=0 and coalesce(config->'issuer'->>'issuerName','')='' and (defaults->>'revision')::integer=0 then return saved;end if;
 select * into d from pro_invoice_drafts where user_id=p_user and id=saved;
 v_today:=((now() at time zone 'America/Costa_Rica')::date)::text;
 prep:=(config->'issuer')||jsonb_build_object('plannedDate',case when defaults->'defaults'->>'dateMode'='today' then v_today else '' end,'saleCondition',defaults->'defaults'->>'saleCondition','creditDays',(defaults->'defaults'->>'creditDays')::integer,'paymentMethod',defaults->'defaults'->>'paymentMethod','orderReference','');
 perform pro_invoice_full_save(p_user,jsonb_build_object('action','update','id',saved,'revision',d.revision,'title',d.title,'notes',d.notes,'receiver',jsonb_build_object('name',d.receiver_name,'identification',d.receiver_identification,'email',d.receiver_email,'phone',d.receiver_phone,'address',d.receiver_address),'preparation',prep));
 return saved;
end $$;

-- ===== Reports =====
-- Open balance of one invoice draft: the same number the draft shows (payments and credit notes applied).
create or replace function public.pro_report_draft_open(p_owner uuid,p_draft uuid) returns bigint language sql stable security invoker set search_path=public,pg_temp as $$
 select greatest(coalesce(public.pro_credit_draft_balance(p_owner,p_draft),0),0)::bigint $$;

create or replace function public.pro_reports_read(p_actor uuid,p_from date default null,p_to date default null) returns jsonb
language plpgsql stable security invoker set search_path=public,pg_temp as $$
declare today date:=(clock_timestamp() at time zone 'America/Costa_Rica')::date;jobs jsonb;aging jsonb;invoiced bigint;collected bigint;outstanding bigint;w record;fin jsonb;
begin
 if p_actor is null then raise exception 'Invalid actor' using errcode='22023';end if;
 if not coalesce(public.pro_private_work_tools_enabled(p_actor),false) then raise exception 'Forbidden' using errcode='42501';end if;
 if (p_from is not null and p_from not between date'2000-01-01' and date'2100-12-31') or (p_to is not null and p_to not between date'2000-01-01' and date'2100-12-31') or (p_from is not null and p_to is not null and p_from>p_to) then raise exception 'Invalid report period' using errcode='22023';end if;
 with d as (
  select d.id,d.total_cents,(d.created_at at time zone 'America/Costa_Rica')::date as day,public.pro_report_draft_open(p_actor,d.id) as open_cents
  from public.pro_invoice_drafts d left join public.pro_invoice_draft_management m on m.user_id=d.user_id and m.draft_id=d.id
  where d.user_id=p_actor and not coalesce(m.archived,false)
   and (p_from is null or (d.created_at at time zone 'America/Costa_Rica')::date>=p_from) and (p_to is null or (d.created_at at time zone 'America/Costa_Rica')::date<=p_to))
 select coalesce(sum(total_cents),0)::bigint,coalesce(sum(open_cents),0)::bigint,
  jsonb_build_object(
   'd0_30',coalesce(sum(open_cents) filter(where today-day<=30),0)::bigint,
   'd31_60',coalesce(sum(open_cents) filter(where today-day between 31 and 60),0)::bigint,
   'd61_90',coalesce(sum(open_cents) filter(where today-day between 61 and 90),0)::bigint,
   'd90_plus',coalesce(sum(open_cents) filter(where today-day>90),0)::bigint,
   'openInvoices',count(*) filter(where open_cents>0))
 into invoiced,outstanding,aging from d;
 select coalesce(sum(p.amount_cents),0)::bigint into collected from public.pro_invoice_payments p
  where p.user_id=p_actor and (p_from is null or p.received_on>=p_from) and (p_to is null or p.received_on<=p_to);
 jobs:='[]'::jsonb;
 for w in select x.id,x.service,x.client,x.stage,coalesce(x.cancelled,false) cancelled,x.start,x."end" from public.pro_work x where x.user_id=p_actor order by coalesce(x.start,'') desc,x.id limit 200 loop
  fin:=public.pro_work_overview_read(p_actor,w.id,'finance');
  if fin is null then continue;end if;
  jobs:=jobs||jsonb_build_array(jsonb_build_object('workId',w.id,'service',coalesce(w.service,''),'client',coalesce(w.client,''),'stage',coalesce(w.stage,''),'cancelled',w.cancelled,
   'start',nullif(left(coalesce(w.start,''),10),''),'end',nullif(left(coalesce(w."end",''),10),''),
   'agreedCents',fin->'agreedCents','agreedNetCents',fin->'agreedNetCents','invoicedCents',coalesce((fin->>'invoicedCents')::bigint,0),'paidCents',coalesce((fin->>'paidCents')::bigint,0),'balanceCents',fin->'balanceCents',
   'costCents',coalesce((fin->>'costCents')::bigint,0),'committedCents',coalesce((fin->>'committedCents')::bigint,0),'resultCents',fin->'resultCents',
   -- Round 11: the result shown next to «Costs and committed» is the one that subtracts both.
   'resultWithCommittedCents',fin->'resultWithCommittedCents','resultBasis',coalesce(fin->>'resultBasis','as_agreed')));
 end loop;
 return jsonb_build_object('today',today,'from',p_from,'to',p_to,'invoicedCents',invoiced,'collectedCents',collected,'outstandingCents',outstanding,'aging',aging,'jobs',jobs,'truncated',(select count(*) from public.pro_work where user_id=p_actor)>200);
end $$;

-- Fix 13: the invoice's own IVA calculation, per line (same expressions as pro_invoice_extras_totals, whose
-- sums are exactly the draft's gross tax and exoneration).
create or replace function public.pro_invoice_vat_lines(p_user uuid,p_id uuid) returns table(line_number integer,treatment text,rate numeric,net numeric,vat_base numeric,gross_tax numeric,exonerated numeric)
language sql stable security invoker set search_path=public,pg_temp as $$
 with gross_lines as (select l.*,round(l.quantity*l.unit_price,5) as gross from public.pro_invoice_edited_lines l where l.user_id=p_user and l.draft_id=p_id),
 bases as (select g.*,g.gross-case when g.discount_type='percent' then round(g.gross*g.discount/100,5) else g.discount end as net from gross_lines g),
 specials as (select t.line_number,t.code,case t.code when '02' then round(t.selective_base*t.rate/100,5) when '04' then round(b.quantity*round(t.quantity_per_unit*t.alcohol_percentage/100,5)*t.amount_per_unit,5) when '05' then round(div(2*((b.quantity*100000)*(t.quantity_per_unit*100000)*(t.amount_per_unit*100000))+(t.beverage_reference_volume*10000000000),2*(t.beverage_reference_volume*10000000000))/100000,5) when '12' then round(b.net*t.rate/100,5) when '03' then round(t.quantity_per_unit*t.amount_per_unit,5) when '06' then round(b.quantity*t.quantity_per_unit*t.amount_per_unit,5) end as amount from public.pro_invoice_line_special_tax t join bases b using(user_id,draft_id,line_number)),
 taxed as (select b.*,t.exemption_rate,b.net+coalesce((select sum(s.amount) from specials s where s.line_number=b.line_number and s.code in ('02','04','05','12')),0) as vat_base from bases b left join public.pro_invoice_line_tax t using(user_id,draft_id,line_number))
 select x.line_number::integer,x.tax_treatment::text,case when x.tax_treatment='vat' then x.tax_rate end,x.net,x.vat_base,
  case when x.tax_treatment='vat' then round(x.vat_base*x.tax_rate/100,5) else 0 end,
  case when x.exemption_rate is not null then round(x.vat_base*x.exemption_rate/100,5) else 0 end
 from taxed x order by x.line_number
$$;

-- Accounting reports: receivables aging per customer, payments received, IVA summary per rate.
create or replace function public.pro_reports_finance_read(p_actor uuid,p_from date default null,p_to date default null) returns jsonb
language plpgsql stable security invoker set search_path=public,pg_temp as $$
declare today date:=(clock_timestamp() at time zone 'America/Costa_Rica')::date;customers jsonb;payments jsonb;vat jsonb;pay_totals jsonb;vat_totals jsonb;refunded bigint;
begin
 if p_actor is null then raise exception 'Invalid actor' using errcode='22023';end if;
 if not coalesce(public.pro_private_work_tools_enabled(p_actor),false) then raise exception 'Forbidden' using errcode='42501';end if;
 if (p_from is not null and p_from not between date'2000-01-01' and date'2100-12-31') or (p_to is not null and p_to not between date'2000-01-01' and date'2100-12-31') or (p_from is not null and p_to is not null and p_from>p_to) then raise exception 'Invalid report period' using errcode='22023';end if;
 -- Receivables aging per customer (invoice drafts of the period, not archived, open balance > 0).
 with d as (
  select d.id,d.client_id,(d.created_at at time zone 'America/Costa_Rica')::date as day,public.pro_report_draft_open(p_actor,d.id) as open_cents
  from public.pro_invoice_drafts d left join public.pro_invoice_draft_management m on m.user_id=d.user_id and m.draft_id=d.id
  where d.user_id=p_actor and not coalesce(m.archived,false)
   and (p_from is null or (d.created_at at time zone 'America/Costa_Rica')::date>=p_from) and (p_to is null or (d.created_at at time zone 'America/Costa_Rica')::date<=p_to)),
 g as (select d.client_id,sum(open_cents)::bigint open_cents,
   coalesce(sum(open_cents) filter(where today-day<=30),0)::bigint d0,coalesce(sum(open_cents) filter(where today-day between 31 and 60),0)::bigint d31,
   coalesce(sum(open_cents) filter(where today-day between 61 and 90),0)::bigint d61,coalesce(sum(open_cents) filter(where today-day>90),0)::bigint d90,
   count(*) filter(where open_cents>0) n,max(today-day) filter(where open_cents>0) oldest
  from d group by d.client_id having sum(open_cents)>0)
 select coalesce(jsonb_agg(jsonb_build_object('clientId',g.client_id,'clientName',coalesce(c.name,''),'openCents',g.open_cents,'d0_30',g.d0,'d31_60',g.d31,'d61_90',g.d61,'d90_plus',g.d90,
   'openInvoices',g.n,'oldestDays',g.oldest) order by g.open_cents desc,coalesce(c.name,''),g.client_id),'[]'::jsonb) into customers
 from g left join public.pro_clients c on c.user_id=p_actor and c.id=g.client_id;
 -- Payments received in the period (by received day); a reversed payment is listed but not counted.
 -- Fix 13: the list shows the latest 500; the totals below count EVERY payment of the period.
 select coalesce(jsonb_agg(x.row order by x.received_on desc,x.id),'[]'::jsonb) into payments from (
  select p.id,p.received_on,p.amount_cents,public.pro_credit_entry_reversed(p_actor,p.entry_id) reversed,
   jsonb_build_object('id',p.id,'receivedOn',p.received_on,'clientName',coalesce(c.name,''),'workTitle',coalesce(w.service,''),'method',coalesce(p.method,''),'reference',coalesce(p.reference,''),
    'amountCents',p.amount_cents,'reversed',public.pro_credit_entry_reversed(p_actor,p.entry_id)) row
  from public.pro_invoice_payments p left join public.pro_clients c on c.user_id=p.user_id and c.id=p.client_id left join public.pro_work w on w.user_id=p.user_id and w.id=p.work_id
  where p.user_id=p_actor and (p_from is null or p.received_on>=p_from) and (p_to is null or p.received_on<=p_to)
  order by p.received_on desc,p.id limit 500) x;
 select jsonb_build_object('count',count(*),'collectedCents',coalesce(sum(p.amount_cents) filter(where not r.reversed),0)::bigint,'reversedCents',coalesce(sum(p.amount_cents) filter(where r.reversed),0)::bigint)
  into pay_totals from public.pro_invoice_payments p cross join lateral (select public.pro_credit_entry_reversed(p_actor,p.entry_id) reversed) r
  where p.user_id=p_actor and (p_from is null or p.received_on>=p_from) and (p_to is null or p.received_on<=p_to);
 select coalesce(sum(r.amount_cents),0)::bigint into refunded from public.pro_credit_refunds r
  where r.owner_id=p_actor and (p_from is null or r.refunded_on>=p_from) and (p_to is null or r.refunded_on<=p_to)
   and not exists(select 1 from public.pro_credit_refund_voids v where v.owner_id=r.owner_id and v.refund_id=r.id);
 pay_totals:=pay_totals||jsonb_build_object('refundedCents',refunded);
 -- IVA summary per rate. Fix 13: drafts with an edited detail use THE SAME per-line calculation as the invoice
 -- (pro_invoice_vat_lines = pro_invoice_extras_totals per line: 5-decimal amounts, IVA base including the
 -- special taxes 02/04/05/12, exoneration on that base); amounts are rounded to cents once per rate. Special
 -- taxes and other charges are not IVA and are left out of the tax. Drafts still without detail: their own
 -- subtotal and tax as one «from the source» row.
 with drafts as (select d.id,d.total_cents,d.tax_cents,exists(select 1 from public.pro_invoice_edited_detail e where e.user_id=d.user_id and e.draft_id=d.id) edited
   from public.pro_invoice_drafts d left join public.pro_invoice_draft_management m on m.user_id=d.user_id and m.draft_id=d.id
   where d.user_id=p_actor and not coalesce(m.archived,false)
    and (p_from is null or (d.created_at at time zone 'America/Costa_Rica')::date>=p_from) and (p_to is null or (d.created_at at time zone 'America/Costa_Rica')::date<=p_to)),
 lines as (select d.id draft,v.* from drafts d cross join lateral public.pro_invoice_vat_lines(p_actor,d.id) v where d.edited),
 per as (select draft,treatment,rate,sum(vat_base) b,sum(gross_tax-exonerated) tx,sum(exonerated) ex,count(*) n from lines group by draft,treatment,rate),
 -- Each invoice's IVA in cents is round(its total IVA); its rate rows share those cents by largest remainder,
 -- so every row is within one cent of its exact amount and the rows add up to the invoices exactly.
 alloc as (select per.*,floor(tx*100) fl,round(sum(tx) over(partition by draft)*100)-sum(floor(tx*100)) over(partition by draft) extra,
   row_number() over(partition by draft order by tx*100-floor(tx*100) desc,treatment,rate) rk from per),
 rows as (select treatment,rate,round(sum(b)*100)::bigint base,sum(fl+case when rk<=extra then 1 else 0 end)::bigint tax,round(sum(ex)*100)::bigint exo,sum(n)::bigint n from alloc group by treatment,rate
  union all select 'source',null,coalesce(sum(total_cents-coalesce(tax_cents,0)),0)::bigint,coalesce(sum(tax_cents),0)::bigint,0,count(*)::bigint from drafts where not edited having count(*)>0)
 select coalesce(jsonb_agg(jsonb_build_object('treatment',treatment,'ratePercent',rate,'baseCents',base,'taxCents',tax,'exoneratedCents',exo,'lines',n)
   order by case treatment when 'vat' then 0 when 'exempt' then 1 when 'not_subject' then 2 when 'pending' then 3 else 4 end,rate desc nulls last),'[]'::jsonb),
  jsonb_build_object('baseCents',coalesce(sum(base),0)::bigint,'taxCents',coalesce(sum(tax),0)::bigint,'exoneratedCents',coalesce(sum(exo),0)::bigint)
 into vat,vat_totals from rows;
 return jsonb_build_object('today',today,'from',p_from,'to',p_to,'customers',customers,'payments',payments,'paymentTotals',pay_totals,'vat',vat,'vatTotals',vat_totals,'paymentsTruncated',(pay_totals->>'count')::integer>500);
end $$;

-- ===== Purchase orders from the job's quote lines, selections and budget =====
create or replace function public.pro_purchase_order_sources(p_actor uuid,p_work text) returns jsonb
language plpgsql stable security invoker set search_path=public,pg_temp as $$
declare quote jsonb;sel jsonb;budget jsonb;g public.pro_private_estimate_work_agreements;
begin
 if not coalesce(public.pro_private_work_tools_enabled(p_actor),false) then raise exception 'Forbidden' using errcode='42501';end if;
 if p_work is null or length(p_work) not between 1 and 160 then raise exception 'Invalid work' using errcode='22023';end if;
 if not exists(select 1 from public.pro_work where user_id=p_actor and id=p_work) then return null;end if;
 select * into g from public.pro_private_estimate_work_agreements where owner_id=p_actor and work_id=p_work order by created_at desc limit 1;
 if g.publication_id is not null then
  select coalesce(jsonb_agg(jsonb_build_object('key','q:'||(l->>'id'),'lineId',l->>'id','description',l->>'description','unit',coalesce(l->>'unit',''),
    'quantity',round((l->>'qtyMilli')::numeric/1000,3),'priceCents',(l->>'unitPriceCents')::bigint,'taxPercent',round(coalesce((l->>'taxBps')::numeric,0)/100,2),
    'unitCostCents',(select (i.content->>'unitCostCents')::bigint from public.pro_private_estimate_items i where i.owner_id=p_actor and i.estimate_id=g.estimate_id and i.content->>'id'=l->>'id' and i.content ? 'unitCostCents' limit 1),
    'group',(select i.content->>'group' from public.pro_private_estimate_items i where i.owner_id=p_actor and i.estimate_id=g.estimate_id and i.content->>'id'=l->>'id' limit 1)) order by n),'[]'::jsonb)
   into quote from public.pro_private_estimate_publications v cross join lateral jsonb_array_elements(v.content->'lines') with ordinality e(l,n) where v.id=g.publication_id;
 end if;
 select coalesce(jsonb_agg(jsonb_build_object('key','s:'||o.id,'optionId',o.id,'itemName',i.name,'name',o.name,'brand',o.brand,'quantity',o.quantity,'unitCents',o.unit_cents,
   'unitCostCents',c.unit_cost_cents,
   'orderedQuantity',coalesce((select sum(pl.quantity) from public.pro_purchase_order_lines pl join public.pro_purchase_orders po on po.owner_id=pl.owner_id and po.id=pl.order_id where pl.owner_id=p_actor and pl.work_id=p_work and pl.selection_option_id=o.id and po.status<>'cancelled'),0))
   order by a.position,i.position),'[]'::jsonb) into sel
  from public.pro_work_selection_items i join public.pro_work_selection_areas a on a.owner_id=i.owner_id and a.id=i.area_id
  join public.pro_work_selection_options o on o.owner_id=i.owner_id and o.id=i.approved_option_id
  left join public.pro_work_selection_option_costs c on c.owner_id=o.owner_id and c.option_id=o.id
  where i.owner_id=p_actor and i.work_id=p_work and i.status='approved' and not i.archived;
 select coalesce(jsonb_agg(jsonb_build_object('key','b:'||c.id,'codeId',c.id,'code',c.code,'title',c.title,'plannedCents',c.planned_cents,
   'committedCents',coalesce((select sum(pl.subtotal_cents+pl.tax_cents) from public.pro_purchase_order_lines pl join public.pro_purchase_orders po on po.owner_id=pl.owner_id and po.id=pl.order_id where pl.owner_id=p_actor and pl.work_id=p_work and pl.budget_code_id=c.id and po.status<>'cancelled'),0)::bigint)
   order by c.code),'[]'::jsonb) into budget
  from public.pro_work_budget_codes c where c.owner_id=p_actor and c.work_id=p_work and c.kind='item' and not c.archived
   and (c.parent_id is null or exists(select 1 from public.pro_work_budget_codes p where p.owner_id=c.owner_id and p.work_id=c.work_id and p.id=c.parent_id and not p.archived));
 return jsonb_build_object('workId',p_work,'quoteTitle',(select title from public.pro_private_estimate_work_agreements where owner_id=p_actor and work_id=p_work order by created_at desc limit 1),
  'quoteLines',coalesce(quote,'[]'::jsonb),'selections',sel,'budget',budget);
end $$;

-- ===== Notifications: payment plan installments due soon (Round 9 center) =====
alter table public.pro_notifications drop constraint if exists pro_notifications_event_check;
alter table public.pro_notifications add constraint pro_notifications_event_check check(event in('task_assigned','task_due','client_message','quote_accepted','quote_changes','invoice_paid','invoice_overdue','bid_received','daily_log_missing','payment_plan_due'));
create or replace function public.pro_notification_events() returns text[] language sql immutable security invoker set search_path=public,pg_temp as $$
 select array['task_assigned','task_due','client_message','quote_accepted','quote_changes','invoice_paid','invoice_overdue','bid_received','daily_log_missing','payment_plan_due']
$$;
-- Same derivation as jobsite-links-autofill-local.sql plus the Round 11 payment plan reminder.
create or replace function public.pro_notifications_sync(p_owner uuid,p_person uuid,p_today date) returns integer
language plpgsql security invoker set search_path=public,pg_temp as $$
declare st jsonb;who text;n integer;plan record;item jsonb;overdue jsonb:='[]'::jsonb;due_soon jsonb:='[]'::jsonb;state jsonb;svc text;
begin
 if not public.pro_notification_person_ok(p_owner,p_person) then raise exception 'Forbidden' using errcode='42501';end if;
 st:=public.pro_notification_settings_json(p_owner,p_person);who:=public.pro_notification_person_name(p_owner,p_person);
 -- Overdue payment-plan installments (after the person's grace days), from the plan's own state.
 for plan in select id,work_id from public.pro_payment_plans where owner_id=p_owner and status='active' limit 200 loop
  svc:=left(coalesce((select service from public.pro_work where user_id=p_owner and id=plan.work_id),'Plan de pagos'),200);
  for item in select value from jsonb_array_elements(coalesce(public.pro_payment_plan_state(p_owner,plan.id,p_today-(st->>'overdueGraceDays')::integer)->'items','[]'::jsonb)) loop
   if item->>'status'='overdue' then overdue:=overdue||jsonb_build_array(jsonb_build_object('key',plan.id::text||':'||coalesce(item->>'seq','')||':'||coalesce(item->>'dueDate',''),
    'title',svc,'body',coalesce(item->>'dueDate',''),
    'link',jsonb_build_object('tab','pro_agenda','cita',plan.work_id,'vistaTrabajo','costs','due',item->>'dueDate','amountCents',coalesce((item->>'amountCents')::bigint,0)-coalesce((item->>'appliedCents')::bigint,0))));end if;
  end loop;
  -- Round 11: installments not paid yet and due within the person's «due soon» days (owner only).
  if p_person=p_owner then
   state:=public.pro_payment_plan_state(p_owner,plan.id,p_today);
   for item in select value from jsonb_array_elements(coalesce(state->'items','[]'::jsonb)) loop
    if item->>'status' in('pending','partial') and item->>'dueDate' is not null and (item->>'dueDate')::date between p_today and p_today+(st->>'dueSoonDays')::integer then
     due_soon:=due_soon||jsonb_build_array(jsonb_build_object('key',plan.id::text||':'||(state->>'revision')||':'||coalesce(item->>'seq','')||':'||(item->>'dueDate'),'title',svc,'body',item->>'dueDate',
      'link',jsonb_build_object('tab','pro_agenda','cita',plan.work_id,'vistaTrabajo','costs','due',item->>'dueDate','amountCents',coalesce((item->>'amountCents')::bigint,0)-coalesce((item->>'appliedCents')::bigint,0))));
    end if;
   end loop;
  end if;
 end loop;
 with events(event,source_key,title,body,link,at) as(
  select 'task_assigned',t.id::text||':'||lower(t.assignee),left(t.title,200),left(w.service,400),jsonb_build_object('tab','pro_agenda','cita',t.work_id,'vistaTrabajo','tasks'),t.updated_at
   from public.pro_work_tasks t join public.pro_work w on w.user_id=t.owner_id and w.id=t.work_id
   where who is not null and t.owner_id=p_owner and not t.archived and t.status='open' and lower(btrim(t.assignee))=lower(who) and t.updated_at>clock_timestamp()-interval '60 days'
  union all
  select 'task_due',t.id::text||':'||t.due_date::text,left(t.title,200),left(w.service,400),jsonb_build_object('tab','pro_agenda','cita',t.work_id,'vistaTrabajo','tasks','due',t.due_date::text,'overdue',t.due_date<p_today),clock_timestamp()
   from public.pro_work_tasks t join public.pro_work w on w.user_id=t.owner_id and w.id=t.work_id
   where t.owner_id=p_owner and not t.archived and t.status='open' and t.due_date is not null and t.due_date<=p_today+(st->>'dueSoonDays')::integer and t.due_date>=p_today-30
    and (who is not null and lower(btrim(t.assignee))=lower(who) or btrim(t.assignee)='' and p_person=p_owner)
  union all
  select 'client_message',m.id::text,left(coalesce(nullif(m.author_name,''),'Cliente'),200),left(m.body,400),jsonb_build_object('tab','pro_agenda','cita',m.work_id,'vistaTrabajo','messages'),m.created_at
   from public.pro_work_messages m where m.owner_id=p_owner and m.side='client' and m.created_at>clock_timestamp()-interval '30 days'
  union all
  select case s.status when 'accepted' then 'quote_accepted' else 'quote_changes' end,p.id::text||':'||s.status||':'||s.revision,left(e.title,200),'',jsonb_build_object('tab','quotes','estimacionPrivada',p.estimate_id::text),p.created_at
   from public.pro_private_estimate_publications p join public.pro_private_estimate_publication_states s on s.publication_id=p.id join public.pro_private_estimates e on e.owner_id=p.owner_id and e.id=p.estimate_id
   where p.owner_id=p_owner and s.status in('accepted','changes_requested') and p.created_at>clock_timestamp()-interval '90 days'
  union all
  select 'invoice_paid',a.id::text,left(d.title,200),a.amount_cents::text,jsonb_build_object('tab','pro_billing','amountCents',a.amount_cents),a.created_at
   from public.pro_invoice_payment_applications a join public.pro_invoice_drafts d on d.user_id=a.user_id and d.id=a.draft_id
   where a.user_id=p_owner and a.created_at>clock_timestamp()-interval '30 days' and not exists(select 1 from public.pro_invoice_payment_voids v where v.user_id=a.user_id and v.application_id=a.id)
  union all
  select 'invoice_overdue',o->>'key',o->>'title',o->>'body',o->'link',clock_timestamp() from jsonb_array_elements(overdue) o
  union all
  select 'payment_plan_due',o->>'key',o->>'title',o->>'body',o->'link',clock_timestamp() from jsonb_array_elements(due_soon) o
  union all
  select 'bid_received',r.package_id::text||':'||r.supplier_id::text,left(b.title,200),left(coalesce((select v.name from public.pro_expense_suppliers v where v.user_id=r.owner_id and v.id=r.supplier_id),''),400),jsonb_build_object('tab','pro_agenda','cita',b.work_id,'vistaTrabajo','bids'),r.recorded_at
   from public.pro_bid_responses r join public.pro_bid_packages b on b.owner_id=r.owner_id and b.id=r.package_id
   where r.owner_id=p_owner and r.recorded_at>clock_timestamp()-interval '30 days'
  union all
  select 'daily_log_missing',w.id||':'||(p_today-1)::text,left(w.service,200),left(coalesce(w.client,''),400),jsonb_build_object('tab','pro_agenda','cita',w.id,'vistaTrabajo','updates','date',(p_today-1)::text),clock_timestamp()
   from public.pro_work w where p_person=p_owner and w.user_id=p_owner and not coalesce(w.cancelled,false)
    and not exists(select 1 from public.pro_daily_logs l where l.owner_id=p_owner and l.work_id=w.id and l.log_date=p_today-1 and not l.archived)
    and(exists(select 1 from public.pro_time_entries e where e.owner_id=p_owner and e.work_id=w.id and e.status='stopped' and e.recorded_on=p_today-1)
     or exists(select 1 from public.pro_work_timers t where t.owner_id=p_owner and t.work_id=w.id and(t.started_at at time zone 'America/Costa_Rica')::date=p_today-1)
     or exists(select 1 from public.pro_work_task_history h where h.owner_id=p_owner and h.work_id=w.id and h.action='complete' and(h.at at time zone 'America/Costa_Rica')::date=p_today-1))),
 ins as(insert into public.pro_notifications(owner_id,person_id,event,source_key,title,body,link,created_at)
  select distinct on(e.event,e.source_key) p_owner,p_person,e.event,e.source_key,e.title,e.body,e.link,least(coalesce(e.at,clock_timestamp()),clock_timestamp())
  from events e where public.pro_notification_enabled(st,e.event,'inApp')
  on conflict(owner_id,person_id,event,source_key) do nothing returning *),
 drafts as(insert into public.pro_notification_email_drafts(owner_id,person_id,notification_id,subject,body)
  select i.owner_id,i.person_id,i.id,left('ContrataCR Pro: '||i.title,200),i.title||case when i.body<>'' then E'\n'||i.body else '' end
  from ins i where public.pro_notification_enabled(st,i.event,'email') returning 1)
 select count(*) into n from ins;
 return n;
end $$;

do $$declare f record;begin
 for f in select p.oid::regprocedure sig from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='public' and p.proname in(
  'pro_company_phone','pro_company_fiscal_identity','pro_invoice_configured_save','pro_report_draft_open','pro_invoice_vat_lines','pro_reports_read','pro_reports_finance_read','pro_purchase_order_sources','pro_notification_events','pro_notifications_sync') loop
  execute format('revoke all on function %s from public,anon,authenticated',f.sig);execute format('grant execute on function %s to service_role',f.sig);end loop;
end $$;
commit;
notify pgrst,'reload schema';

-- ===== task-files-selection-visibility-local.sql =====
-- LOCAL PRO ONLY. Round 11 (2026-11-15), leftovers of Round 10 (Houzz Pro parity rows 16 and 62).
--  * Task attachments (row 16): the person who uploaded a task file, or the account owner, can RENAME the
--    name shown and send it to the task's TRASH / RESTORE it. The stored object, its canonical download
--    name, size and digest never change (files stay immutable); a side table keeps the shown name and the
--    trash flag with a revision (CAS 40001), idempotent receipts per actionId and immutable history.
--    pro_team_task_discussion_read lists ready files without the trashed ones; kind «trash» lists those.
--    Same per-job grant rules as the discussion (write grant required).
--  * Selections (row 62): per item, the owner can hide the PRICE and/or the LINK of its options from the
--    customer. The customer read (pro_work_selection_client_item_json) then returns null for unit/total and
--    for the link, plus priceHidden/linkHidden; the owner keeps seeing everything. CAS, receipts, history.
-- Patterns: RLS on, service_role only, security invoker, CAS 40001, idempotent actionId, immutable history.
begin;
create table if not exists public.pro_team_task_file_meta(
 owner_id uuid not null references public.profiles(id) on delete cascade,file_id uuid primary key references public.pro_team_task_files(id) on delete cascade,
 display_name text check(display_name is null or (length(btrim(display_name)) between 1 and 160 and display_name !~ '[[:cntrl:]]')),
 trashed boolean not null default false,trashed_at timestamptz,revision integer not null check(revision>0),updated_at timestamptz not null default clock_timestamp(),
 check(trashed=(trashed_at is not null)));
create table if not exists public.pro_team_task_file_meta_history(
 owner_id uuid not null references public.profiles(id) on delete cascade,action_id uuid not null,file_id uuid not null references public.pro_team_task_files(id) on delete cascade,
 actor_id uuid not null,action text not null check(action in('file_rename','file_trash','file_restore')),before_value jsonb not null,after_value jsonb not null,at timestamptz not null default clock_timestamp(),
 primary key(action_id,file_id));
create table if not exists public.pro_team_task_file_meta_actions(
 actor_id uuid not null references public.profiles(id) on delete cascade,action_id uuid not null,input jsonb not null,result jsonb not null,at timestamptz not null default clock_timestamp(),primary key(actor_id,action_id));
create table if not exists public.pro_work_selection_item_visibility(
 owner_id uuid not null references public.profiles(id) on delete cascade,item_id uuid not null,work_id text not null,
 hide_price boolean not null default false,hide_link boolean not null default false,revision integer not null check(revision>0),updated_at timestamptz not null default clock_timestamp(),
 primary key(owner_id,item_id),foreign key(owner_id,item_id) references public.pro_work_selection_items(owner_id,id) on delete cascade);
create table if not exists public.pro_work_selection_visibility_history(
 owner_id uuid not null references public.profiles(id) on delete cascade,action_id uuid not null,item_id uuid not null,work_id text not null,before_value jsonb not null,after_value jsonb not null,
 at timestamptz not null default clock_timestamp(),primary key(owner_id,action_id,item_id));
create table if not exists public.pro_work_selection_visibility_actions(
 owner_id uuid not null references public.profiles(id) on delete cascade,action_id uuid not null,input jsonb not null,result jsonb not null,at timestamptz not null default clock_timestamp(),primary key(owner_id,action_id));
do $$declare t text;begin
 foreach t in array array['pro_team_task_file_meta_history','pro_team_task_file_meta_actions','pro_work_selection_visibility_history','pro_work_selection_visibility_actions'] loop
  execute format('drop trigger if exists %I on public.%I',t||'_immutable',t);
  execute format('create trigger %I before update or delete on public.%I for each row when (pg_trigger_depth()=0) execute function public.pro_round10_immutable()',t||'_immutable',t);
 end loop;
 foreach t in array array['pro_team_task_file_meta','pro_team_task_file_meta_history','pro_team_task_file_meta_actions','pro_work_selection_item_visibility','pro_work_selection_visibility_history','pro_work_selection_visibility_actions'] loop
  execute format('alter table public.%I enable row level security',t);execute format('revoke all on public.%I from public,anon,authenticated',t);execute format('grant all on public.%I to service_role',t);
 end loop;
end $$;

-- ===== Task files: shown name and trash =====
create or replace function public.pro_team_task_file_json(p_file public.pro_team_task_files) returns jsonb language sql stable security invoker set search_path=public,pg_temp as $$
 select jsonb_build_object('id',p_file.id,'taskId',p_file.task_id,'name',p_file.name,'mimeType',p_file.mime_type,'sizeBytes',p_file.size_bytes,'sha256',p_file.sha256,'ready',p_file.ready,'actorId',p_file.actor_id,'actorName',p_file.actor_name,'createdAt',p_file.created_at,
  'displayName',coalesce(m.display_name,p_file.name),'trashed',coalesce(m.trashed,false),'metaRevision',coalesce(m.revision,0))
 from (select 1) one left join public.pro_team_task_file_meta m on m.file_id=p_file.id;
$$;
create or replace function public.pro_team_task_discussion_read(p_actor uuid,p_grant uuid,p_task uuid,p_kind text,p_after uuid default null) returns jsonb language plpgsql stable security invoker set search_path=public,pg_temp as $$
declare g public.pro_team_grants;t public.pro_work_tasks;items jsonb;cursor_at timestamptz;cursor_id uuid;trash boolean:=p_kind='trash';
begin
 g:=public.pro_team_task_discussion_context(p_actor,p_grant,p_task,false);
 select * into t from public.pro_work_tasks where owner_id=g.owner_id and work_id=g.work_id and id=p_task;
 if p_kind='comments' then
  if p_after is not null then select at into cursor_at from public.pro_team_task_comments where owner_id=g.owner_id and work_id=g.work_id and task_id=p_task and id=p_after;if not found then raise exception 'Invalid comment cursor' using errcode='22023';end if;end if;
  select coalesce(jsonb_agg(public.pro_team_task_comment_json(c::public.pro_team_task_comments) order by c.at desc,c.id desc),'[]'::jsonb) into items from(select * from public.pro_team_task_comments where owner_id=g.owner_id and work_id=g.work_id and task_id=p_task and (p_after is null or (at,id)<(cursor_at,p_after)) order by at desc,id desc limit 21)c;
 elsif p_kind in('files','trash') then
  if p_after is not null then select created_at into cursor_at from public.pro_team_task_files where owner_id=g.owner_id and work_id=g.work_id and task_id=p_task and id=p_after and ready;if not found then raise exception 'Invalid file cursor' using errcode='22023';end if;end if;
  select coalesce(jsonb_agg(public.pro_team_task_file_json(f::public.pro_team_task_files) order by f.created_at desc,f.id desc),'[]'::jsonb) into items from(
   select x.* from public.pro_team_task_files x left join public.pro_team_task_file_meta m on m.file_id=x.id
   where x.owner_id=g.owner_id and x.work_id=g.work_id and x.task_id=p_task and x.ready and coalesce(m.trashed,false)=trash and (p_after is null or(x.created_at,x.id)<(cursor_at,p_after)) order by x.created_at desc,x.id desc limit 21)f;
 else raise exception 'Invalid discussion view' using errcode='22023';end if;
 if jsonb_array_length(items)>20 then cursor_id:=(items->19->>'id')::uuid;items:=items-20;end if;
 return jsonb_build_object('grant',public.pro_team_shared_grant_json(g,p_actor),'task',public.pro_team_task_json(t),'items',items,'nextCursor',cursor_id);
end $$;
create or replace function public.pro_team_task_file_manage(p_actor uuid,p_input jsonb) returns jsonb language plpgsql security invoker set search_path=public,pg_temp as $$
declare act text;keys text[];aid uuid;g public.pro_team_grants;f public.pro_team_task_files;m public.pro_team_task_file_meta;receipt public.pro_team_task_file_meta_actions;before_json jsonb;answer jsonb;v_name text;
begin
 if jsonb_typeof(p_input) is distinct from 'object' then raise exception 'Invalid file action' using errcode='22023';end if;
 act:=p_input->>'action';select array_agg(x order by x) into keys from jsonb_object_keys(p_input) x;
 if keys is distinct from (case act when 'file_rename' then array['action','actionId','fileId','grantId','name','revision','taskId'] when 'file_trash' then array['action','actionId','fileId','grantId','revision','taskId'] when 'file_restore' then array['action','actionId','fileId','grantId','revision','taskId'] end)
  or jsonb_typeof(p_input->'revision') is distinct from 'number' or not coalesce((p_input->>'revision')~'^[0-9]{1,9}$',false) then raise exception 'Unexpected file action fields' using errcode='22023';end if;
 begin aid:=(p_input->>'actionId')::uuid;g:=public.pro_team_task_discussion_context(p_actor,(p_input->>'grantId')::uuid,(p_input->>'taskId')::uuid,true);
  select * into f from public.pro_team_task_files where id=(p_input->>'fileId')::uuid and owner_id=g.owner_id and work_id=g.work_id and task_id=(p_input->>'taskId')::uuid and ready;
 exception when invalid_text_representation then raise exception 'Invalid identifiers' using errcode='22023';end;
 if f.id is null then raise exception 'File unavailable' using errcode='P0002';end if;
 if p_actor<>g.owner_id and f.actor_id<>p_actor then raise exception 'Only the owner or the uploader' using errcode='42501';end if;
 if act='file_rename' then
  if jsonb_typeof(p_input->'name') is distinct from 'string' then raise exception 'Invalid name' using errcode='22023';end if;
  v_name:=btrim(p_input->>'name');if length(v_name) not between 1 and 160 or v_name ~ '[[:cntrl:]]' then raise exception 'Invalid name' using errcode='22023';end if;
 end if;
 perform pg_advisory_xact_lock(hashtextextended('pro-task-file-meta:'||p_actor::text||':'||aid::text,0));
 select * into receipt from public.pro_team_task_file_meta_actions where actor_id=p_actor and action_id=aid;
 if found then if receipt.input is distinct from p_input then raise exception 'Action id reused' using errcode='22023';end if;return receipt.result||jsonb_build_object('replayed',true);end if;
 -- Fix 13: serialize per file BEFORE reading the revision, so two first writes (revision 0) give one 409.
 perform pg_advisory_xact_lock(hashtextextended('pro-task-file-meta-target:'||f.id::text,0));
 select * into m from public.pro_team_task_file_meta where file_id=f.id for update;
 if coalesce(m.revision,0)<>(p_input->>'revision')::integer then raise exception 'File changed' using errcode='40001';end if;
 if act='file_trash' and coalesce(m.trashed,false) or act='file_restore' and not coalesce(m.trashed,false) then raise exception 'Nothing to change' using errcode='22023';end if;
 before_json:=jsonb_build_object('displayName',coalesce(m.display_name,f.name),'trashed',coalesce(m.trashed,false));
 insert into public.pro_team_task_file_meta(owner_id,file_id,display_name,trashed,trashed_at,revision)
  values(g.owner_id,f.id,case when act='file_rename' then v_name end,act='file_trash',case when act='file_trash' then clock_timestamp() end,1)
  on conflict(file_id) do update set display_name=case when act='file_rename' then v_name else public.pro_team_task_file_meta.display_name end,
   trashed=case when act='file_rename' then public.pro_team_task_file_meta.trashed else act='file_trash' end,
   trashed_at=case when act='file_rename' then public.pro_team_task_file_meta.trashed_at when act='file_trash' then clock_timestamp() end,
   revision=public.pro_team_task_file_meta.revision+1,updated_at=clock_timestamp();
 answer:=jsonb_build_object('action',act,'file',public.pro_team_task_file_json(f));
 insert into public.pro_team_task_file_meta_history(owner_id,action_id,file_id,actor_id,action,before_value,after_value)
  values(g.owner_id,aid,f.id,p_actor,act,before_json,jsonb_build_object('displayName',answer->'file'->'displayName','trashed',answer->'file'->'trashed'));
 insert into public.pro_team_task_file_meta_actions(actor_id,action_id,input,result) values(p_actor,aid,p_input,answer);
 return answer;
end $$;
-- A trashed file can still be downloaded by its id (it is kept, not deleted); lists hide it.

-- ===== Selections: hide price / link from the customer per item =====
create or replace function public.pro_work_selection_visibility_json(p_owner uuid,p_item uuid) returns jsonb language sql stable security invoker set search_path=public,pg_temp as $$
 select jsonb_build_object('hidePrice',coalesce(v.hide_price,false),'hideLink',coalesce(v.hide_link,false),'revision',coalesce(v.revision,0))
 from (select 1) one left join public.pro_work_selection_item_visibility v on v.owner_id=p_owner and v.item_id=p_item $$;
create or replace function public.pro_work_selection_visibility_read(p_owner uuid,p_work text) returns jsonb language plpgsql stable security invoker set search_path=public,pg_temp as $$
begin
 if not coalesce(public.pro_private_work_tools_enabled(p_owner),false) then raise exception 'Forbidden' using errcode='42501';end if;
 if p_work is null or length(p_work) not between 1 and 160 then raise exception 'Invalid work' using errcode='22023';end if;
 if not exists(select 1 from public.pro_work where user_id=p_owner and id=p_work) then return null;end if;
 return jsonb_build_object('workId',p_work,'items',coalesce((select jsonb_agg(jsonb_build_object('itemId',i.id,'name',i.name,'areaName',a.name,'published',i.published)||public.pro_work_selection_visibility_json(p_owner,i.id) order by a.position,i.position)
  from public.pro_work_selection_items i join public.pro_work_selection_areas a on a.owner_id=i.owner_id and a.id=i.area_id where i.owner_id=p_owner and i.work_id=p_work and not i.archived and not a.archived),'[]'::jsonb));
end $$;
create or replace function public.pro_work_selection_visibility_mutate(p_owner uuid,p_input jsonb) returns jsonb language plpgsql security invoker set search_path=public,pg_temp as $$
declare keys text[];aid uuid;wid text;receipt public.pro_work_selection_visibility_actions;ref jsonb;item public.pro_work_selection_items;v public.pro_work_selection_item_visibility;before_json jsonb;n integer:=0;answer jsonb;
begin
 if not coalesce(public.pro_private_work_tools_enabled(p_owner),false) then raise exception 'Forbidden' using errcode='42501';end if;
 select array_agg(x order by x) into keys from jsonb_object_keys(p_input) x;
 if jsonb_typeof(p_input) is distinct from 'object' or keys is distinct from array['action','actionId','items','workId'] or p_input->>'action'<>'visibility_set' or jsonb_typeof(p_input->'workId') is distinct from 'string'
  or jsonb_typeof(p_input->'items') is distinct from 'array' or jsonb_array_length(p_input->'items') not between 1 and 100 then raise exception 'Invalid visibility action' using errcode='22023';end if;
 begin aid:=(p_input->>'actionId')::uuid;exception when others then raise exception 'Invalid action id' using errcode='22023';end;
 wid:=p_input->>'workId';if not exists(select 1 from public.pro_work where user_id=p_owner and id=wid) then raise exception 'Forbidden' using errcode='42501';end if;
 perform pg_advisory_xact_lock(hashtextextended('pro-selection-visibility:'||p_owner::text||':'||aid::text,0));
 select * into receipt from public.pro_work_selection_visibility_actions where owner_id=p_owner and action_id=aid;
 if found then if receipt.input is distinct from p_input then raise exception 'Action id reused' using errcode='22023';end if;return receipt.result||jsonb_build_object('replayed',true);end if;
 perform pg_advisory_xact_lock(hashtextextended('pro-work-selection:'||p_owner::text||':'||wid,0));
 for ref in select value from jsonb_array_elements(p_input->'items') loop
  select array_agg(x order by x) into keys from jsonb_object_keys(ref) x;
  if keys is distinct from array['hideLink','hidePrice','itemId','revision'] or jsonb_typeof(ref->'hidePrice') is distinct from 'boolean' or jsonb_typeof(ref->'hideLink') is distinct from 'boolean'
   or jsonb_typeof(ref->'revision') is distinct from 'number' or not coalesce(ref->>'revision'~'^[0-9]{1,9}$',false) then raise exception 'Invalid visibility item' using errcode='22023';end if;
  begin select * into item from public.pro_work_selection_items where owner_id=p_owner and work_id=wid and id=(ref->>'itemId')::uuid and not archived;exception when others then raise exception 'Invalid item' using errcode='22023';end;
  if item.id is null then raise exception 'Item unavailable' using errcode='P0002';end if;
  select * into v from public.pro_work_selection_item_visibility where owner_id=p_owner and item_id=item.id for update;
  if coalesce(v.revision,0)<>(ref->>'revision')::integer then raise exception 'Visibility changed' using errcode='40001';end if;
  before_json:=public.pro_work_selection_visibility_json(p_owner,item.id);
  insert into public.pro_work_selection_item_visibility(owner_id,item_id,work_id,hide_price,hide_link,revision) values(p_owner,item.id,wid,(ref->>'hidePrice')::boolean,(ref->>'hideLink')::boolean,1)
   on conflict(owner_id,item_id) do update set hide_price=excluded.hide_price,hide_link=excluded.hide_link,revision=public.pro_work_selection_item_visibility.revision+1,updated_at=clock_timestamp();
  insert into public.pro_work_selection_visibility_history(owner_id,action_id,item_id,work_id,before_value,after_value) values(p_owner,aid,item.id,wid,before_json,public.pro_work_selection_visibility_json(p_owner,item.id));
  n:=n+1;item:=null;
 end loop;
 answer:=jsonb_build_object('action','visibility_set','updated',n);
 insert into public.pro_work_selection_visibility_actions(owner_id,action_id,input,result) values(p_owner,aid,p_input,answer);
 return answer;
end $$;
-- Supersedes selection-catalog-local.sql: the customer copy honours «hide price» and «hide link».
create or replace function public.pro_work_selection_client_item_json(p_row public.pro_work_selection_items) returns jsonb
language sql stable security invoker set search_path=public,pg_temp as $$
 select jsonb_build_object('id',p_row.id,'areaId',p_row.area_id,'name',p_row.name,'dueDate',p_row.due_date,'state',public.pro_work_selection_state(p_row),
  'approvedOptionId',p_row.approved_option_id,'approvedAt',p_row.approved_at,'clientComment',p_row.client_comment,'recommendedOptionId',p_row.recommended_option_id,'revision',p_row.revision,
  'priceHidden',coalesce(v.hide_price,false),'linkHidden',coalesce(v.hide_link,false),
  'options',coalesce((select jsonb_agg(jsonb_build_object('id',o.id,'name',o.name,'brand',o.brand,'url',case when coalesce(v.hide_link,false) then null else o.url end,'quantity',o.quantity,
   'unitCents',case when coalesce(v.hide_price,false) then null else o.unit_cents end,'totalCents',case when coalesce(v.hide_price,false) then null else o.total_cents end,
   'clientNotes',o.client_notes,'hasImage',o.image_file_id is not null or exists(select 1 from public.pro_work_selection_option_sources s where s.owner_id=o.owner_id and s.option_id=o.id and s.image_path is not null)) order by o.position) from public.pro_work_selection_options o where o.owner_id=p_row.owner_id and o.item_id=p_row.id and not o.archived),'[]'::jsonb))
 from (select 1) one left join public.pro_work_selection_item_visibility v on v.owner_id=p_row.owner_id and v.item_id=p_row.id;
$$;
do $$declare f record;begin
 for f in select p.oid::regprocedure sig from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='public' and p.proname in(
  'pro_team_task_file_json','pro_team_task_discussion_read','pro_team_task_file_manage','pro_work_selection_visibility_json','pro_work_selection_visibility_read','pro_work_selection_visibility_mutate','pro_work_selection_client_item_json') loop
  execute format('revoke all on function %s from public,anon,authenticated',f.sig);execute format('grant execute on function %s to service_role',f.sig);end loop;
end $$;
commit;
notify pgrst,'reload schema';

-- ===== client-portal-overview-local.sql =====
-- LOCAL PRO ONLY. Round 12 (2026-11-15): customer portal (Houzz Pro parity rows 33, 22, 24, 28-31) and
-- Round 11 leftovers.
--  * Project overview for the linked customer (row 33): one read that summarises what the customer of a
--    job can already see, built ONLY from the existing customer readers (same audience and visibility
--    switches: quotes, contracts, selections, extras/changes, payment plan, finances, schedule, messages,
--    files). Approvals waiting for the customer, money (when «Finanzas» is on), next installment (when
--    «Plan de pagos» is on), schedule (when «Cronograma» is on), unread messages and latest files (when
--    «Archivos» is on). Nothing new is disclosed: a hidden section stays null.
--  * Customer bell reminders for the professional's payment plan (row 57 leftover): in-app notifications
--    (main `notifications` table, own type `pro_payment_plan_client`, push suppressed, never email/SMS)
--    for an installment due within 3 days or overdue, only for a linked customer whose plan section is
--    visible. Idempotent through a receipt per plan revision/installment/due date/action/recipient.
--    ContrataCR never finances anything: this is the professional's own plan, no interest, no third party.
--  * Printable selections sheet (Round 11 leftover): respects «hide price» per item (the link was never
--    printed). Hidden prices are not printed nor added to the approved total.
-- Patterns: RLS on, service_role only, security invoker, immutable receipts, CR dates (America/Costa_Rica).
begin;

-- ===== Customer project overview =====
create or replace function public.pro_client_project_overview(p_actor uuid,p_request uuid) returns jsonb
language plpgsql stable security invoker set search_path=public,pg_temp as $$
declare r public.pro_appointment_requests;w public.pro_work;settings public.pro_client_dashboards;today date:=(now() at time zone 'America/Costa_Rica')::date;
 quotes jsonb;contracts jsonb;selections jsonb;changes jsonb;plan jsonb;finances jsonb;schedule jsonb;files jsonb;approvals jsonb:='[]'::jsonb;
 next_item jsonb;overdue_n integer:=0;overdue_c bigint:=0;installments jsonb;money jsonb;sched jsonb;msgs jsonb;recent jsonb;next_ms jsonb;total_n bigint:=0;done_n bigint:=0;last_msg public.pro_work_messages;
begin
 if not exists(select 1 from public.profiles where id=p_actor and not coalesce(is_disabled,false)) then raise exception 'Forbidden' using errcode='42501';end if;
 if p_request is null then raise exception 'Invalid overview query' using errcode='22023';end if;
 select * into r from public.pro_appointment_requests where id=p_request and client_user_id=p_actor and work_id is not null;
 if not found then return null;end if;
 select * into w from public.pro_work where user_id=r.owner_id and id=r.work_id;
 if not found or r.status not in('confirmed','completed') then return jsonb_build_object('visible',false);end if;
 select * into settings from public.pro_client_dashboards where owner_id=r.owner_id and work_id=r.work_id;
 -- Approvals waiting for this customer (each from its own customer reader).
 quotes:=coalesce(public.pro_client_project_quotes_read(p_actor,p_request)->'items','[]'::jsonb);
 approvals:=approvals||coalesce((select jsonb_agg(jsonb_build_object('kind','quote','id',q->>'publicationId','title',q->>'title','amountCents',q->'totalCents','currency',q->>'currency','date',q->>'sharedAt') order by q->>'sharedAt')
  from jsonb_array_elements(quotes) q where q->>'status'='shared'),'[]'::jsonb);
 contracts:=public.pro_contracts_client_read(p_actor,p_request);
 if coalesce((contracts->>'visible')::boolean,false) then
  approvals:=approvals||coalesce((select jsonb_agg(jsonb_build_object('kind','contract','id',c->>'id','title',coalesce(c->'content'->>'title',c->>'code'),'code',c->>'code','date',c->>'sharedAt'))
   from jsonb_array_elements(contracts->'contracts') c where coalesce((c->>'canRespond')::boolean,false)),'[]'::jsonb);
 end if;
 selections:=public.pro_work_selections_client_read(p_actor,p_request);
 if coalesce((selections->>'visible')::boolean,false) then
  approvals:=approvals||coalesce((select jsonb_agg(jsonb_build_object('kind','selection','id',i->>'id','title',i->>'name','area',a->>'name','date',i->>'dueDate','overdue',(i->>'dueDate') is not null and (i->>'dueDate')::date<today) order by i->>'dueDate' nulls last)
   from jsonb_array_elements(selections->'areas') a cross join lateral jsonb_array_elements(a->'items') i where i->>'state'='pending_client'),'[]'::jsonb);
 end if;
 changes:=public.pro_work_changes_page(p_actor,'',p_request,null);
 if changes is not null and changes->>'side'='client' then
  approvals:=approvals||coalesce((select jsonb_agg(jsonb_build_object('kind','change','id',c->>'id','title',c->>'reason','amountCents',c->'deltaCents','date',c->>'createdAt'))
   from jsonb_array_elements(changes->'items') c where c->>'status'='proposed' and not coalesce((c->>'stale')::boolean,false)),'[]'::jsonb);
 end if;
 plan:=public.pro_payment_plan_client_read(p_actor,p_request);
 if coalesce((plan->>'visible')::boolean,false) and jsonb_typeof(plan->'plan')='object' then
  if coalesce((plan->'plan'->>'canAccept')::boolean,false) then
   approvals:=approvals||jsonb_build_array(jsonb_build_object('kind','payment_plan','id',plan->'plan'->>'planId','title',null,'amountCents',plan->'plan'->'totalCents','date',plan->'plan'->>'revisionCreatedAt'));
  end if;
  select i into next_item from jsonb_array_elements(plan->'plan'->'items') i where i->>'status' in('pending','partial','overdue') and i->>'dueDate' is not null order by (i->>'dueDate')::date,(i->>'seq')::integer limit 1;
  select count(*),coalesce(sum((i->>'amountCents')::bigint-(i->>'appliedCents')::bigint),0) into overdue_n,overdue_c from jsonb_array_elements(plan->'plan'->'items') i where i->>'status'='overdue';
  installments:=jsonb_build_object('remainingCents',plan->'plan'->'remainingCents','overdueCount',overdue_n,'overdueCents',overdue_c,
   'next',case when next_item is null then null else jsonb_build_object('dueDate',next_item->>'dueDate','amountCents',(next_item->>'amountCents')::bigint-(next_item->>'appliedCents')::bigint,'status',next_item->>'status') end);
 end if;
 finances:=public.pro_client_finances_client_read(p_actor,p_request);
 if coalesce((finances->>'visible')::boolean,false) then
  money:=jsonb_build_object('agreedCents',finances->'summary'->'agreedCents','paidCents',finances->'summary'->'paidCents','balanceCents',finances->'summary'->'balanceCents','invoicedCents',finances->'summary'->'invoicedCents');
 end if;
 schedule:=public.pro_work_schedule_client_read(p_actor,p_request);
 if coalesce((schedule->>'visible')::boolean,false) then
  select m into next_ms from jsonb_array_elements(schedule->'milestones') m where (m->>'date')::date>=today order by (m->>'date')::date limit 1;
  select coalesce(sum((p->>'total')::bigint),0),coalesce(sum((p->>'done')::bigint),0) into total_n,done_n from jsonb_array_elements(schedule->'phases') p;
  total_n:=total_n+coalesce((schedule->'general'->>'total')::bigint,0);done_n:=done_n+coalesce((schedule->'general'->>'done')::bigint,0);
  sched:=jsonb_build_object('nextMilestone',next_ms,'total',total_n,'done',done_n,
   'plannedEnd',(select max(x) from (select p->>'plannedEnd' x from jsonb_array_elements(schedule->'phases') p union all select schedule->'general'->>'plannedEnd') y));
 end if;
 if public.pro_work_message_side(p_actor,p_request)='client' then
  select * into last_msg from public.pro_work_messages where request_id=p_request order by created_at desc,id desc limit 1;
  msgs:=jsonb_build_object('unread',public.pro_work_message_unread(p_request,'client'),
   'last',case when last_msg.id is null then null else jsonb_build_object('side',last_msg.side,'body',left(last_msg.body,140),'createdAt',last_msg.created_at) end);
 end if;
 if coalesce(settings.show_files,true) then
  files:=public.pro_work_files_client_read(p_actor,p_request,null);
  select coalesce(jsonb_agg(jsonb_build_object('id',f->>'id','name',f->>'name','mimeType',f->>'mimeType','publishedAt',f->>'publishedAt')),'[]'::jsonb) into recent
   from (select f from jsonb_array_elements(coalesce(files->'items','[]'::jsonb)) f limit 3) x;
  recent:=jsonb_build_object('items',recent,'more',jsonb_array_length(coalesce(files->'items','[]'::jsonb))>3);
 end if;
 return jsonb_build_object('visible',true,'requestId',p_request,'today',to_char(today,'YYYY-MM-DD'),'workTitle',w.service,
  'professionalName',coalesce((select nullif(btrim(business_name),'') from public.professionals where profile_id=r.owner_id limit 1),public.pro_team_name(r.owner_id)),
  'stage',case when coalesce(w.cancelled,false) then 'cancelled' when w.stage='completed' or r.status='completed' then 'completed' else coalesce(w.stage,'new') end,
  'nextVisit',case when r.origin<>'project_invite' and not coalesce(w.cancelled,false) and w.stage='scheduled' and pro_instant(w.start)>now() then pro_appointment_time(pro_instant(w.start)) end,
  'approvals',approvals,'finances',money,'installments',installments,'schedule',sched,'messages',msgs,'files',recent);
end $$;

-- ===== Printable selections sheet: respect «hide price» =====
create or replace function public.pro_work_selection_print_read(p_owner uuid,p_work text) returns jsonb language plpgsql stable security invoker set search_path=public,pg_temp as $$
declare w public.pro_work;
begin
 if not coalesce(public.pro_private_work_tools_enabled(p_owner),false) then raise exception 'Forbidden' using errcode='42501';end if;
 select * into w from public.pro_work where user_id=p_owner and id=p_work;if not found then return null;end if;
 return jsonb_build_object('workId',w.id,'service',w.service,'client',coalesce(w.client,''),'today',public.pro_work_selection_today(),
  'areas',coalesce((select jsonb_agg(jsonb_build_object('name',a.name,'items',x.items) order by a.position) from public.pro_work_selection_areas a
   join lateral(select jsonb_agg(jsonb_build_object('name',i.name,'state',public.pro_work_selection_state(i),'dueDate',i.due_date,'approvedAt',i.approved_at,'tracking',public.pro_work_selection_tracking_json(p_owner,i.id)->>'status',
     'priceHidden',coalesce(v.hide_price,false),
     'option',(select jsonb_build_object('name',o.name,'brand',o.brand,'quantity',o.quantity,'unitCents',case when coalesce(v.hide_price,false) then null else o.unit_cents end,'totalCents',case when coalesce(v.hide_price,false) then null else o.total_cents end,'approved',o.id=i.approved_option_id) from public.pro_work_selection_options o where o.owner_id=i.owner_id and o.id=coalesce(i.approved_option_id,i.recommended_option_id)),
     'optionCount',(select count(*) from public.pro_work_selection_options o where o.owner_id=i.owner_id and o.item_id=i.id and not o.archived)) order by i.position) items
    from public.pro_work_selection_items i left join public.pro_work_selection_item_visibility v on v.owner_id=i.owner_id and v.item_id=i.id
    where i.owner_id=a.owner_id and i.area_id=a.id and not i.archived) x on x.items is not null
   where a.owner_id=p_owner and a.work_id=p_work and not a.archived),'[]'::jsonb));
end $$;

-- ===== Customer bell: payment plan installments due soon / overdue =====
do $$declare prior text;begin
 select pg_get_expr(conbin,conrelid) into prior from pg_constraint where conrelid='public.notifications'::regclass and conname='notifications_type_check' and contype='c';
 if prior is null then raise exception 'Notification type contract not found';end if;
 if position('pro_payment_plan_client' in prior)=0 then
  alter table public.notifications drop constraint notifications_type_check;
  execute format('alter table public.notifications add constraint notifications_type_check check ((%s) or type in (''pro_payment_plan_client''))',prior);
 end if;
end $$;
do $$begin
 if not exists(select 1 from pg_constraint where conrelid='public.notifications'::regclass and conname='pro_payment_plan_client_notification_data_check') then
  alter table public.notifications add constraint pro_payment_plan_client_notification_data_check check(
   type<>'pro_payment_plan_client' or coalesce((
    data is not null and jsonb_typeof(data)='object' and data @> '{"version":1,"push_suppressed":true}'::jsonb
    and data ?& array['version','request_id','action','due_date','link','push_suppressed']
    and (data-array['version','request_id','action','due_date','link','push_suppressed'])='{}'::jsonb
    and jsonb_typeof(data->'request_id')='string' and (data->>'request_id')~'^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
    and jsonb_typeof(data->'action')='string' and data->>'action' in('installment_due_soon','installment_overdue')
    and jsonb_typeof(data->'due_date')='string' and (data->>'due_date')~'^\d{4}-\d{2}-\d{2}$'
    and jsonb_typeof(data->'link')='string' and data->>'link'='/dashboard/profesional?tab=appointments&citaSolicitud='||(data->>'request_id')
   ),false));
 end if;
end $$;
create table if not exists public.pro_client_installment_notices(
 owner_id uuid not null references public.profiles(id) on delete cascade,
 plan_id uuid not null,plan_revision integer not null check(plan_revision>0),seq integer not null check(seq>=0),due_date date not null,
 action text not null check(action in('installment_due_soon','installment_overdue')),
 recipient_id uuid not null references public.profiles(id) on delete cascade,
 request_id uuid not null references public.pro_appointment_requests(id) on delete cascade,
 notification_id uuid references public.notifications(id) on delete set null,
 created_at timestamptz not null default clock_timestamp(),
 primary key(plan_id,plan_revision,seq,due_date,action,recipient_id));
alter table public.pro_client_installment_notices enable row level security;
revoke all on public.pro_client_installment_notices from public,anon,authenticated;
grant all on public.pro_client_installment_notices to service_role;
-- Receipts are immutable once linked; a dismissed (deleted) notification does not reissue the reminder.
create or replace function public.pro_client_installment_notice_immutable() returns trigger
language plpgsql security invoker set search_path=public,pg_temp as $$
begin
 if tg_op='DELETE' then raise exception 'Installment notice receipts are immutable' using errcode='23514';end if;
 if (to_jsonb(new)-'notification_id') is distinct from (to_jsonb(old)-'notification_id') or (old.notification_id is not null and new.notification_id is not null and new.notification_id<>old.notification_id) then
  raise exception 'Installment notice receipts are immutable' using errcode='23514';end if;
 return new;
end $$;
drop trigger if exists pro_client_installment_notice_immutable on public.pro_client_installment_notices;
create trigger pro_client_installment_notice_immutable before update or delete on public.pro_client_installment_notices for each row
 when (pg_trigger_depth()=0) execute function public.pro_client_installment_notice_immutable();

create or replace function public.pro_client_installment_reminders_run(p_owner uuid,p_today date default null,p_recipient uuid default null) returns integer
language plpgsql security invoker set search_path=public,pg_temp as $$
declare today date:=coalesce(p_today,(now() at time zone 'America/Costa_Rica')::date);plan record;req record;state jsonb;item jsonb;act text;due date;n integer:=0;nid uuid;
begin
 if p_owner is null or not exists(select 1 from public.profiles where id=p_owner and not coalesce(is_disabled,false)) then raise exception 'Forbidden' using errcode='42501';end if;
 for plan in select id,work_id from public.pro_payment_plans where owner_id=p_owner and status='active' order by id limit 200 loop
  for req in select r.id,r.client_user_id from public.pro_appointment_requests r
    join public.pro_client_dashboards d on d.owner_id=r.owner_id and d.work_id=r.work_id and coalesce(d.show_payment_plan,false)
    join public.profiles p on p.id=r.client_user_id and not coalesce(p.is_disabled,false)
    where r.owner_id=p_owner and r.work_id=plan.work_id and r.client_user_id is not null and r.client_user_id<>p_owner and r.status in('confirmed','completed')
     and (p_recipient is null or r.client_user_id=p_recipient) loop
   state:=public.pro_payment_plan_state(p_owner,plan.id,today);
   for item in select value from jsonb_array_elements(coalesce(state->'items','[]'::jsonb)) loop
    due:=(item->>'dueDate')::date;
    act:=case when item->>'status'='overdue' then 'installment_overdue'
     when item->>'status' in('pending','partial') and due between today and today+3 then 'installment_due_soon' end;
    if act is null or due is null then continue;end if;
    insert into public.pro_client_installment_notices(owner_id,plan_id,plan_revision,seq,due_date,action,recipient_id,request_id)
     values(p_owner,plan.id,(state->>'revision')::integer,(item->>'seq')::integer,due,act,req.client_user_id,req.id) on conflict do nothing;
    if not found then continue;end if;
    insert into public.notifications(user_id,type,title,message,data,read) values(req.client_user_id,'pro_payment_plan_client',
     case act when 'installment_overdue' then 'Cuota vencida' else 'Cuota próxima a vencer' end,
     case act when 'installment_overdue' then 'Una cuota de su plan de pagos está vencida. Revísela en su proyecto.' else 'Una cuota de su plan de pagos vence pronto. Revísela en su proyecto.' end,
     jsonb_build_object('version',1,'request_id',req.id,'action',act,'due_date',to_char(due,'YYYY-MM-DD'),'link','/dashboard/profesional?tab=appointments&citaSolicitud='||req.id::text,'push_suppressed',true),false)
     returning id into nid;
    update public.pro_client_installment_notices set notification_id=nid where plan_id=plan.id and plan_revision=(state->>'revision')::integer and seq=(item->>'seq')::integer and due_date=due and action=act and recipient_id=req.client_user_id;
    n:=n+1;
   end loop;
  end loop;
 end loop;
 return n;
end $$;

do $$declare f record;begin
 for f in select p.oid::regprocedure sig from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='public' and p.proname in(
  'pro_client_project_overview','pro_work_selection_print_read','pro_client_installment_notice_immutable','pro_client_installment_reminders_run') loop
  execute format('revoke all on function %s from public,anon,authenticated',f.sig);execute format('grant execute on function %s to service_role',f.sig);end loop;
end $$;
notify pgrst,'reload schema';
commit;

-- ===== design-levels-local.sql =====
-- LOCAL PRO ONLY. Round 12 (2026-11-15): design tools (Houzz Pro parity row 63).
--  * Floor plans: a plan may name the LEVEL (storey) it draws ({name, order}; the editor lists plans by level and
--    starts a new level from the walls of the current one) and carry furniture/fixture OBJECTS (footprint, kind,
--    size, quarter-turn rotation). The content validator below accepts both optional keys, strictly; the stored
--    summary (rooms, area, perimeter, walls, openings) is unchanged and objects never count as area.
-- Patterns: same writer (CAS, actionId, immutable history) as floor-plans-local.sql; service_role only.
begin;
create or replace function public.pro_floor_content_ok(c jsonb) returns boolean
language plpgsql immutable security invoker set search_path=public,pg_temp as $$
declare x jsonb;p jsonb;
begin
 if jsonb_typeof(c)<>'object' or jsonb_typeof(c->'walls')<>'array' or jsonb_typeof(c->'openings')<>'array' or jsonb_typeof(c->'rooms')<>'array' or jsonb_typeof(c->'dimensions')<>'array'
  or jsonb_array_length(c->'walls')>500 or jsonb_array_length(c->'openings')>300 or jsonb_array_length(c->'rooms')>100 or jsonb_array_length(c->'dimensions')>200
  or not public.pro_floor_num(c->'wallHeight') or (c->>'wallHeight')::numeric<=0 then return false;end if;
 for x in select * from jsonb_array_elements(c->'walls') loop
  if jsonb_typeof(x->'id')<>'string' or not public.pro_floor_point_ok(x->'a') or not public.pro_floor_point_ok(x->'b') or not public.pro_floor_num(x->'thickness') then return false;end if;end loop;
 for x in select * from jsonb_array_elements(c->'openings') loop
  if x->>'kind' not in('door','window') or jsonb_typeof(x->'wallId')<>'string' or not public.pro_floor_num(x->'offset') or not public.pro_floor_num(x->'width')
   or not exists(select 1 from jsonb_array_elements(c->'walls') w where w->>'id'=x->>'wallId') then return false;end if;end loop;
 for x in select * from jsonb_array_elements(c->'rooms') loop
  if jsonb_typeof(x->'id')<>'string' or coalesce(length(btrim(x->>'name')),0) not between 1 and 80 or jsonb_typeof(x->'points')<>'array' or jsonb_array_length(x->'points') not between 3 and 100 then return false;end if;
  for p in select * from jsonb_array_elements(x->'points') loop if not public.pro_floor_point_ok(p) then return false;end if;end loop;end loop;
 for x in select * from jsonb_array_elements(c->'dimensions') loop
  if not public.pro_floor_point_ok(x->'a') or not public.pro_floor_point_ok(x->'b') then return false;end if;end loop;
 -- Round 12 (row 63): optional level {name 1..60, order -5..50} and furniture/fixture objects (≤300).
 if c ? 'level' and (jsonb_typeof(c->'level')<>'object' or (select array_agg(k order by k) from jsonb_object_keys(c->'level') k) is distinct from array['name','order']
  or coalesce(length(btrim(c->'level'->>'name')),0) not between 1 and 60 or jsonb_typeof(c->'level'->'order')<>'number' or (c->'level'->>'order')!~'^-?[0-9]+$' or (c->'level'->>'order')::integer not between -5 and 50) then return false;end if;
 if c ? 'objects' then
  if jsonb_typeof(c->'objects')<>'array' or jsonb_array_length(c->'objects')>300 then return false;end if;
  for x in select * from jsonb_array_elements(c->'objects') loop
   if jsonb_typeof(x)<>'object' or (select array_agg(k order by k) from jsonb_object_keys(x) k) is distinct from array['d','id','kind','rotation','w','x','y']
    or jsonb_typeof(x->'id')<>'string' or x->>'kind' not in('bed','sofa','table','chair','desk','wardrobe','cabinet','stove','fridge','sink','toilet','shower','bathtub','washer','stairs')
    or not public.pro_floor_num(x->'x') or not public.pro_floor_num(x->'y') or not public.pro_floor_num(x->'w') or not public.pro_floor_num(x->'d')
    or (x->>'w')::numeric not between 0.1 and 50 or (x->>'d')::numeric not between 0.1 and 50 or x->>'rotation' not in('0','90','180','270') then return false;end if;
  end loop;
 end if;
 return true;
end $$;
revoke all on function public.pro_floor_content_ok(jsonb) from public,anon,authenticated;
grant execute on function public.pro_floor_content_ok(jsonb) to service_role;
commit;

-- ===== getting-started-local.sql =====
-- LOCAL PRO ONLY. Round 12 (2026-11-15): «Primeros pasos» (getting started) inside Pro (Houzz Pro parity row 74).
-- One read that derives, from the account's OWN existing records, which first steps are done: company profile,
-- document branding, first customer, first quote, first job, a customer following a job, the customer view
-- configured, a billing document or payment plan, and a team member. Nothing is stored or sent; the checklist
-- disappears from «Inicio» when every step is done. Read only, service_role only, security invoker.
begin;
create or replace function public.pro_getting_started_read(p_actor uuid) returns jsonb
language plpgsql stable security invoker set search_path=public,pg_temp as $$
declare steps jsonb;
begin
 if not coalesce(public.pro_private_work_tools_enabled(p_actor),false) then raise exception 'Forbidden' using errcode='42501';end if;
 steps:=jsonb_build_array(
  jsonb_build_object('key','profile','done',exists(select 1 from public.professionals p where p.profile_id=p_actor and coalesce(btrim(p.business_name),'')<>''
   and (coalesce(btrim(p.call_phone),'')<>'' or coalesce(btrim(p.whatsapp),'')<>'') and coalesce(btrim(p.formatted_address),'')<>'')),
  jsonb_build_object('key','branding','done',exists(select 1 from public.pro_document_branding b where b.owner_id=p_actor)),
  jsonb_build_object('key','customer','done',exists(select 1 from public.pro_clients c where c.user_id=p_actor and not c.archived)),
  jsonb_build_object('key','quote','done',exists(select 1 from public.pro_private_estimates e where e.owner_id=p_actor)),
  jsonb_build_object('key','job','done',exists(select 1 from public.pro_work w where w.user_id=p_actor and not coalesce(w.cancelled,false))),
  jsonb_build_object('key','client_linked','done',exists(select 1 from public.pro_appointment_requests r where r.owner_id=p_actor and r.client_user_id is not null and r.work_id is not null and r.status in('confirmed','completed'))),
  jsonb_build_object('key','client_view','done',exists(select 1 from public.pro_client_dashboards d where d.owner_id=p_actor)),
  jsonb_build_object('key','billing','done',exists(select 1 from public.pro_invoice_drafts i where i.user_id=p_actor) or exists(select 1 from public.pro_payment_plans p where p.owner_id=p_actor)),
  jsonb_build_object('key','team','done',exists(select 1 from public.pro_company_members m where m.owner_id=p_actor)));
 return jsonb_build_object('steps',steps,'done',(select count(*) from jsonb_array_elements(steps) s where (s->>'done')::boolean),'total',jsonb_array_length(steps));
end $$;
revoke all on function public.pro_getting_started_read(uuid) from public,anon,authenticated;
grant execute on function public.pro_getting_started_read(uuid) to service_role;
notify pgrst,'reload schema';
commit;

-- ===== takeoff-deductions-local.sql =====
-- LOCAL PRO ONLY. Fix 14 — parity register row 66: area subtraction in Mediciones.
-- An AREA measurement can be marked as an opening («hueco»: window, door, column…) of another
-- area measurement on the same plan page. The parent's quantity becomes
--   net = gross − Σ(openings)   (never below 0), then its multiplier and waste apply to the net,
-- so «Send to quote» quotes the net area through the unchanged line builder. An opening is
-- never quoted by itself. Same writer rules as the rest of Mediciones: owner with private work
-- tools, CAS on the opening's revision (40001), idempotent actionId with an immutable receipt.
-- Nothing is shared with the customer, sent, charged or invoiced.
begin;

alter table public.pro_work_takeoff_measurements add column if not exists deduct_from uuid;
do $$begin
 if not exists(select 1 from pg_constraint where conname='pro_work_takeoff_deduct_from_fk') then
  alter table public.pro_work_takeoff_measurements add constraint pro_work_takeoff_deduct_from_fk
   foreign key(owner_id,deduct_from) references public.pro_work_takeoff_measurements(owner_id,id) on delete set null (deduct_from);
 end if;
 if not exists(select 1 from pg_constraint where conname='pro_work_takeoff_deduct_not_self') then
  alter table public.pro_work_takeoff_measurements add constraint pro_work_takeoff_deduct_not_self check(deduct_from is null or deduct_from<>id);
 end if;
end $$;
create index if not exists pro_work_takeoff_measurement_deduct on public.pro_work_takeoff_measurements(owner_id,deduct_from) where deduct_from is not null;

-- The link is valid only between two AREA measurements of the same job, plan and page, one level deep.
create or replace function public.pro_work_takeoff_deduct_check() returns trigger
language plpgsql security invoker set search_path=public,pg_temp as $$
declare parent public.pro_work_takeoff_measurements;
begin
 if new.deduct_from is null then return new;end if;
 if new.kind<>'area' then raise exception 'Only an area can be subtracted' using errcode='23514';end if;
 select * into parent from public.pro_work_takeoff_measurements where owner_id=new.owner_id and id=new.deduct_from;
 if not found or parent.kind<>'area' or parent.work_id<>new.work_id or parent.plan_id<>new.plan_id or parent.page_number<>new.page_number
  then raise exception 'Subtract from an area of the same page' using errcode='23514';end if;
 if parent.deduct_from is not null then raise exception 'An opening cannot have openings' using errcode='23514';end if;
 if exists(select 1 from public.pro_work_takeoff_measurements c where c.owner_id=new.owner_id and c.deduct_from=new.id) then raise exception 'This area already has openings' using errcode='23514';end if;
 return new;
end $$;
drop trigger if exists pro_work_takeoff_deduct_check on public.pro_work_takeoff_measurements;
create trigger pro_work_takeoff_deduct_check before insert or update of deduct_from,kind,plan_id,page_number on public.pro_work_takeoff_measurements
 for each row execute function public.pro_work_takeoff_deduct_check();

-- Gross base of one measurement (the original formula of takeoffs-local.sql, without multiplier or waste).
create or replace function public.pro_work_takeoff_base(p_row public.pro_work_takeoff_measurements,p_page public.pro_work_takeoff_pages) returns numeric
language plpgsql immutable security invoker set search_path=public,pg_temp as $$
declare cal numeric;
begin
 if p_row.kind='count' then return coalesce(p_row.manual_milli,jsonb_array_length(p_row.points)*1000);end if;
 if p_row.manual_milli is not null then return p_row.manual_milli;end if;
 if p_page.cal_length_milli is null then return null;end if;
 cal:=public.pro_work_takeoff_px_distance(p_page.cal_x1,p_page.cal_y1,p_page.cal_x2,p_page.cal_y2,p_page.width_px,p_page.height_px);
 if p_row.kind='length' then return round(public.pro_work_takeoff_px_length(p_row.points,p_page.width_px,p_page.height_px)*p_page.cal_length_milli/cal);end if;
 return round(public.pro_work_takeoff_px_area(p_row.points,p_page.width_px,p_page.height_px)*p_page.cal_length_milli*p_page.cal_length_milli/(cal*cal*1000));
end $$;

-- Result with openings: the same keys as before; deductFrom only on an opening, and grossMilli/deductedMilli/openings only on an area with openings
-- (a measurement without openings keeps exactly the previous payload).
create or replace function public.pro_work_takeoff_result(p_row public.pro_work_takeoff_measurements,p_page public.pro_work_takeoff_pages) returns jsonb
language plpgsql stable security invoker set search_path=public,pg_temp as $$
declare base numeric;gross numeric;cut numeric:=0;openings integer:=0;missing boolean:=false;total numeric;base_unit text;total_unit text;o public.pro_work_takeoff_measurements;ob numeric;
begin
 base_unit:=case p_row.kind when 'count' then 'u' when 'area' then p_page.unit||'2' else p_page.unit end;
 total_unit:=case when p_row.multiplier_mode='height' then p_page.unit||'2' else base_unit end;
 base:=public.pro_work_takeoff_base(p_row,p_page);
 if base is null then
  return jsonb_build_object('baseMilli',null,'totalMilli',null,'baseUnit',base_unit,'unit',total_unit,'needsScale',true)||case when p_row.deduct_from is null then '{}'::jsonb else jsonb_build_object('deductFrom',p_row.deduct_from) end;
 end if;
 gross:=base;
 if p_row.kind='area' and p_row.deduct_from is null then
  for o in select * from public.pro_work_takeoff_measurements where owner_id=p_row.owner_id and deduct_from=p_row.id and not archived order by position loop
   ob:=public.pro_work_takeoff_base(o,p_page);openings:=openings+1;
   if ob is null then missing:=true;else cut:=cut+ob;end if;
  end loop;
  if missing then
   return jsonb_build_object('baseMilli',null,'totalMilli',null,'baseUnit',base_unit,'unit',total_unit,'needsScale',true);
  end if;
  base:=greatest(gross-cut,0);
 end if;
 total:=base;
 if p_row.multiplier_mode<>'none' then total:=round(total*p_row.multiplier_milli/1000);end if;
 if p_row.waste_bps>0 then total:=round(total*(10000+p_row.waste_bps)/10000);end if;
 return jsonb_build_object('baseMilli',base,'totalMilli',total,'baseUnit',base_unit,'unit',total_unit,'needsScale',false)
  ||case when p_row.deduct_from is null then '{}'::jsonb else jsonb_build_object('deductFrom',p_row.deduct_from) end
  ||case when openings>0 then jsonb_build_object('grossMilli',gross,'deductedMilli',cut,'openings',openings) else '{}'::jsonb end;
end $$;

create table if not exists public.pro_work_takeoff_deduction_actions(
 actor_id uuid not null references public.profiles(id) on delete cascade,action_id uuid not null,
 work_id text not null,measurement_id uuid not null,input jsonb not null,result jsonb not null,at timestamptz not null default now(),
 primary key(actor_id,action_id)
);
create or replace function public.pro_work_takeoff_deduction_immutable() returns trigger
language plpgsql security invoker set search_path=public,pg_temp as $$
begin raise exception 'Takeoff deduction receipts are immutable' using errcode='23514';end $$;
drop trigger if exists pro_work_takeoff_deduction_action_immutable on public.pro_work_takeoff_deduction_actions;
create trigger pro_work_takeoff_deduction_action_immutable before update on public.pro_work_takeoff_deduction_actions for each row execute function public.pro_work_takeoff_deduction_immutable();

-- {action:'deduction_set', actionId, workId, id, revision, parentId}  /  {action:'deduction_clear', actionId, workId, id, revision}
create or replace function public.pro_work_takeoff_deduction_mutate(p_actor uuid,p_input jsonb) returns jsonb
language plpgsql security invoker set search_path=public,pg_temp as $$
declare act text;aid uuid;wid text;mid uuid;pid uuid;rev integer;keys text[];receipt public.pro_work_takeoff_deduction_actions;m public.pro_work_takeoff_measurements;p public.pro_work_takeoff_measurements;result jsonb;
begin
 if not coalesce(public.pro_private_work_tools_enabled(p_actor),false) then raise exception 'Forbidden' using errcode='42501';end if;
 if jsonb_typeof(p_input) is distinct from 'object' then raise exception 'Invalid deduction' using errcode='22023';end if;
 act:=p_input->>'action';
 select array_agg(key order by key) into keys from jsonb_object_keys(p_input) key;
 if act='deduction_set' and keys is distinct from array['action','actionId','id','parentId','revision','workId']
  or act='deduction_clear' and keys is distinct from array['action','actionId','id','revision','workId']
  or act is null or act not in('deduction_set','deduction_clear') then raise exception 'Invalid deduction fields' using errcode='22023';end if;
 if jsonb_typeof(p_input->'workId') is distinct from 'string' or jsonb_typeof(p_input->'actionId') is distinct from 'string' or jsonb_typeof(p_input->'id') is distinct from 'string'
  or act='deduction_set' and jsonb_typeof(p_input->'parentId') is distinct from 'string' then raise exception 'Invalid deduction fields' using errcode='22023';end if;
 wid:=p_input->>'workId';if length(wid) not between 1 and 160 then raise exception 'Invalid deduction identity' using errcode='22023';end if;
 aid:=(p_input->>'actionId')::uuid;mid:=(p_input->>'id')::uuid;if act='deduction_set' then pid:=(p_input->>'parentId')::uuid;end if;
 rev:=public.pro_work_takeoff_int(p_input->'revision',1,2147483646)::integer;
 -- Replay: the same actionId returns its receipt; a different body with that id is a conflict.
 select * into receipt from public.pro_work_takeoff_deduction_actions where actor_id=p_actor and action_id=aid;
 if found then if receipt.input<>p_input then raise exception 'Action reused' using errcode='22023';end if;return receipt.result;end if;
 -- Closing round (security review B2): same per-job lock as pro_work_takeoffs_mutate, whose send_estimate
 -- branch checks pro_work_takeoff_send_check under it; an opening cannot be marked while its area is being quoted.
 perform pg_advisory_xact_lock(hashtextextended('pro-work-takeoff:'||p_actor::text||':'||wid,0));
 perform pg_advisory_xact_lock(hashtextextended('pro-takeoff-deduction:'||p_actor::text||':'||wid,0));
 select * into m from public.pro_work_takeoff_measurements where owner_id=p_actor and work_id=wid and id=mid for update;
 if not found then raise exception 'Unknown measurement' using errcode='P0002';end if;
 if m.archived then raise exception 'Archived measurement' using errcode='22023';end if;
 if m.revision<>rev then raise exception 'Measurement changed' using errcode='40001';end if;
 if act='deduction_set' then
  select * into p from public.pro_work_takeoff_measurements where owner_id=p_actor and work_id=wid and id=pid;
  if not found or p.archived then raise exception 'Unknown area' using errcode='22023';end if;
  update public.pro_work_takeoff_measurements set deduct_from=pid,revision=revision+1,updated_at=now() where owner_id=p_actor and id=mid returning * into m;
 else
  update public.pro_work_takeoff_measurements set deduct_from=null,revision=revision+1,updated_at=now() where owner_id=p_actor and id=mid returning * into m;
 end if;
 result:=jsonb_build_object('measurement',public.pro_work_takeoff_measurement_json(m));
 insert into public.pro_work_takeoff_deduction_actions(actor_id,action_id,work_id,measurement_id,input,result) values(p_actor,aid,wid,mid,p_input,result);
 return result;
end $$;

-- An opening is never quoted on its own (its area is already taken off its parent).
create or replace function public.pro_work_takeoff_send_check(p_actor uuid,p_work text,p_ids uuid[]) returns boolean
language sql stable security invoker set search_path=public,pg_temp as $$
 select not exists(select 1 from public.pro_work_takeoff_measurements where owner_id=p_actor and work_id=p_work and id=any(p_ids) and deduct_from is not null);
$$;

do $$declare f record;begin
 alter table public.pro_work_takeoff_deduction_actions enable row level security;
 revoke all on public.pro_work_takeoff_deduction_actions from public,anon,authenticated;
 grant select,insert on public.pro_work_takeoff_deduction_actions to service_role;
 -- Closing round (security review B1): receipts are never deleted by server code; account deletion still cascades.
 revoke update,delete,truncate on public.pro_work_takeoff_deduction_actions from service_role;
 for f in select p.oid::regprocedure signature,p.proname from pg_proc p join pg_namespace n on n.oid=p.pronamespace
  where n.nspname='public' and p.proname in('pro_work_takeoff_deduct_check','pro_work_takeoff_base','pro_work_takeoff_result','pro_work_takeoff_deduction_immutable','pro_work_takeoff_deduction_mutate','pro_work_takeoff_send_check') loop
  execute format('revoke all on function %s from public,anon,authenticated',f.signature);
  if f.proname not in('pro_work_takeoff_deduct_check','pro_work_takeoff_deduction_immutable') then execute format('grant execute on function %s to service_role',f.signature);end if;
 end loop;
end $$;
notify pgrst,'reload schema';
commit;

-- ===== quote-line-decisions-local.sql =====
-- LOCAL PRO ONLY. Fix 14 — parity register row 39: visual proposal with per-item customer approval.
-- On a quote version shared with a linked customer (pro_private_estimate_publications), the customer
-- approves or declines EACH line («partida»), with an optional note, while the version is open
-- (shared / changes requested). The professional sees every decision and the approved total; the
-- version's own answer (accept / decline / ask for changes) is unchanged and stays the formal reply.
-- A line shows the image of its catalog item (pro_product_details) when the estimate line with the
-- same id is linked to an item that has one. Writer: CAS per line (revision, 40001), idempotent
-- actionId with an immutable receipt, immutable history. Nothing is sent, charged or invoiced.
begin;

create table if not exists public.pro_quote_line_decisions(
 publication_id uuid not null references public.pro_private_estimate_publications(id) on delete cascade,
 line_id uuid not null,decision text check(decision in('approved','declined')),
 note text not null default '' check(length(note)<=300 and note=btrim(note)),
 decided_by uuid not null references public.profiles(id) on delete cascade,
 revision integer not null default 1 check(revision>0),updated_at timestamptz not null default clock_timestamp(),
 primary key(publication_id,line_id)
);
create table if not exists public.pro_quote_line_decision_history(
 publication_id uuid not null references public.pro_private_estimate_publications(id) on delete cascade,
 line_id uuid not null,revision integer not null,action_id uuid not null,actor_id uuid not null,
 decision text,note text not null default '',at timestamptz not null default clock_timestamp(),
 primary key(publication_id,line_id,revision)
);
create table if not exists public.pro_quote_line_decision_actions(
 actor_id uuid not null references public.profiles(id) on delete cascade,action_id uuid not null,
 input jsonb not null,result jsonb not null,at timestamptz not null default clock_timestamp(),primary key(actor_id,action_id)
);
create or replace function public.pro_quote_line_decision_immutable() returns trigger
language plpgsql security invoker set search_path=public,pg_temp as $$
begin raise exception 'Line decision history and receipts are immutable' using errcode='23514';end $$;
drop trigger if exists pro_quote_line_decision_history_immutable on public.pro_quote_line_decision_history;
-- Update only: deleting the publication or the account still cascades (same rule as the other Pro histories).
create trigger pro_quote_line_decision_history_immutable before update on public.pro_quote_line_decision_history for each row execute function public.pro_quote_line_decision_immutable();
drop trigger if exists pro_quote_line_decision_action_immutable on public.pro_quote_line_decision_actions;
create trigger pro_quote_line_decision_action_immutable before update on public.pro_quote_line_decision_actions for each row execute function public.pro_quote_line_decision_immutable();

-- Line total in cents (same order as the document: quantity × price, discount, then tax).
create or replace function public.pro_quote_line_total(p_line jsonb) returns bigint
language sql immutable security invoker set search_path=public,pg_temp as $$
 with b as(select round(coalesce((p_line->>'qtyMilli')::numeric,0)*coalesce((p_line->>'unitPriceCents')::numeric,0)/1000) base),
 d as(select base-round(base*coalesce((p_line->>'discountBps')::numeric,0)/10000) net from b)
 select (net+round(net*coalesce((p_line->>'taxBps')::numeric,0)/10000))::bigint from d;
$$;

create or replace function public.pro_quote_line_decisions_read(p_actor uuid,p_publication uuid) returns jsonb
language plpgsql security invoker set search_path=public,pg_temp as $$
declare side text;v public.pro_private_estimate_publications;s public.pro_private_estimate_publication_states;lines jsonb;open boolean;
begin
 side:=public.pro_private_estimate_publication_authorize(p_actor,p_publication,false);
 select * into v from public.pro_private_estimate_publications where id=p_publication;
 select * into s from public.pro_private_estimate_publication_states where publication_id=p_publication;
 open:=s.status in('shared','changes_requested') and coalesce(public.pro_private_work_tools_enabled(v.owner_id),false)
  and(v.content->>'validUntil' is null or(v.content->>'validUntil')::date>=(clock_timestamp() at time zone 'America/Costa_Rica')::date);
 select coalesce(jsonb_agg(jsonb_build_object('lineId',l.value->>'id','position',l.ord,'description',l.value->>'description','unit',l.value->>'unit',
   'qtyMilli',(l.value->>'qtyMilli')::bigint,'unitPriceCents',(l.value->>'unitPriceCents')::bigint,'totalCents',public.pro_quote_line_total(l.value),
   'hasImage',exists(select 1 from public.pro_private_estimate_items i join public.pro_product_details pd on pd.user_id=v.owner_id and pd.product_id=i.content->>'catalogProductId' and pd.image_id is not null
     where i.owner_id=v.owner_id and i.estimate_id=v.estimate_id and i.id::text=l.value->>'id'),
   'decision',d.decision,'note',coalesce(d.note,''),'revision',coalesce(d.revision,0),'decidedAt',d.updated_at) order by l.ord),'[]'::jsonb) into lines
  from jsonb_array_elements(coalesce(v.content->'lines','[]'::jsonb)) with ordinality l(value,ord)
  left join public.pro_quote_line_decisions d on d.publication_id=p_publication and d.line_id::text=l.value->>'id';
 return jsonb_build_object('publicationId',p_publication,'side',side,'status',s.status,'version',v.version,'title',v.content->>'title','currency',coalesce(v.content->>'currency','CRC'),
  'canDecide',side='client' and open,'lines',lines,'totalCents',(v.content->>'totalCents')::bigint,
  'approvedCents',(select coalesce(sum((x->>'totalCents')::bigint),0) from jsonb_array_elements(lines) x where x->>'decision'='approved'),
  'declinedCents',(select coalesce(sum((x->>'totalCents')::bigint),0) from jsonb_array_elements(lines) x where x->>'decision'='declined'),
  'approvedCount',(select count(*) from jsonb_array_elements(lines) x where x->>'decision'='approved'),
  'declinedCount',(select count(*) from jsonb_array_elements(lines) x where x->>'decision'='declined'),
  'pendingCount',(select count(*) from jsonb_array_elements(lines) x where x->>'decision' is null));
end $$;

-- {actionId, publicationId, lineId, decision:'approved'|'declined'|null, note, revision}. Only the linked customer, only while the version is open.
create or replace function public.pro_quote_line_decide(p_actor uuid,p_input jsonb) returns jsonb
language plpgsql security invoker set search_path=public,pg_temp as $$
declare aid uuid;pid uuid;lid uuid;dec text;note_text text;rev integer;side text;receipt public.pro_quote_line_decision_actions;v public.pro_private_estimate_publications;s public.pro_private_estimate_publication_states;d public.pro_quote_line_decisions;result jsonb;next_rev integer;
begin
 if jsonb_typeof(p_input) is distinct from 'object' or (select array_agg(k order by k) from jsonb_object_keys(p_input) k) is distinct from array['actionId','decision','lineId','note','publicationId','revision']
  or jsonb_typeof(p_input->'actionId') is distinct from 'string' or jsonb_typeof(p_input->'publicationId') is distinct from 'string' or jsonb_typeof(p_input->'lineId') is distinct from 'string'
  or jsonb_typeof(p_input->'decision') not in('string','null') or jsonb_typeof(p_input->'note') is distinct from 'string' or jsonb_typeof(p_input->'revision') is distinct from 'number'
  then raise exception 'Invalid line decision' using errcode='22023';end if;
 aid:=(p_input->>'actionId')::uuid;pid:=(p_input->>'publicationId')::uuid;lid:=(p_input->>'lineId')::uuid;dec:=p_input->>'decision';note_text:=btrim(p_input->>'note');
 if dec is not null and dec not in('approved','declined') or length(note_text)>300 then raise exception 'Invalid line decision' using errcode='22023';end if;
 if (p_input->>'revision')::numeric<>trunc((p_input->>'revision')::numeric) or (p_input->>'revision')::numeric not between 0 and 2147483646 then raise exception 'Invalid revision' using errcode='22023';end if;
 rev:=(p_input->>'revision')::integer;
 select * into receipt from public.pro_quote_line_decision_actions where actor_id=p_actor and action_id=aid;
 if found then if receipt.input<>p_input then raise exception 'Action reused' using errcode='22023';end if;return receipt.result;end if;
 side:=public.pro_private_estimate_publication_authorize(p_actor,pid,true);
 if side<>'client' then raise exception 'Only the customer decides' using errcode='42501';end if;
 perform pg_advisory_xact_lock(hashtextextended('pro-quote-line:'||pid::text||':'||lid::text,0));
 select * into v from public.pro_private_estimate_publications where id=pid;
 select * into s from public.pro_private_estimate_publication_states where publication_id=pid for share;
 if s.status not in('shared','changes_requested') or (v.content->>'validUntil') is not null and (v.content->>'validUntil')::date<(clock_timestamp() at time zone 'America/Costa_Rica')::date
  then raise exception 'This version is closed' using errcode='22023';end if;
 if not exists(select 1 from jsonb_array_elements(coalesce(v.content->'lines','[]'::jsonb)) l where l->>'id'=lid::text) then raise exception 'Unknown line' using errcode='P0002';end if;
 select * into d from public.pro_quote_line_decisions where publication_id=pid and line_id=lid for update;
 if coalesce(d.revision,0)<>rev then raise exception 'Line decision changed' using errcode='40001';end if;
 next_rev:=rev+1;
 insert into public.pro_quote_line_decisions(publication_id,line_id,decision,note,decided_by,revision,updated_at) values(pid,lid,dec,note_text,p_actor,next_rev,clock_timestamp())
  on conflict(publication_id,line_id) do update set decision=excluded.decision,note=excluded.note,decided_by=excluded.decided_by,revision=excluded.revision,updated_at=excluded.updated_at;
 insert into public.pro_quote_line_decision_history(publication_id,line_id,revision,action_id,actor_id,decision,note) values(pid,lid,next_rev,aid,p_actor,dec,note_text);
 result:=public.pro_quote_line_decisions_read(p_actor,pid);
 insert into public.pro_quote_line_decision_actions(actor_id,action_id,input,result) values(p_actor,aid,p_input,result);
 return result;
end $$;

-- Image of a line's catalog item, for the owner or the recipient of that version (storage metadata only).
create or replace function public.pro_quote_line_image(p_actor uuid,p_publication uuid,p_line uuid) returns jsonb
language plpgsql security invoker set search_path=public,pg_temp as $$
declare v public.pro_private_estimate_publications;pd public.pro_product_details;
begin
 perform public.pro_private_estimate_publication_authorize(p_actor,p_publication,false);
 select * into v from public.pro_private_estimate_publications where id=p_publication;
 if not exists(select 1 from jsonb_array_elements(coalesce(v.content->'lines','[]'::jsonb)) l where l->>'id'=p_line::text) then return null;end if;
 select x.* into pd from public.pro_private_estimate_items i join public.pro_product_details x on x.user_id=v.owner_id and x.product_id=i.content->>'catalogProductId'
  where i.owner_id=v.owner_id and i.estimate_id=v.estimate_id and i.id=p_line and x.image_id is not null;
 if not found then return null;end if;
 return jsonb_build_object('objectPath',pd.image_path,'sha256',pd.image_sha256,'sizeBytes',pd.image_size,'imageId',pd.image_id);
end $$;

do $$declare t text;f record;begin
 foreach t in array array['pro_quote_line_decisions','pro_quote_line_decision_history','pro_quote_line_decision_actions'] loop
  execute format('alter table public.%I enable row level security',t);
  execute format('revoke all on public.%I from public,anon,authenticated',t);
  execute format('grant select,insert,update on public.%I to service_role',t);
  -- Closing round (security review B1): Supabase grants ALL to service_role by default; server code may
  -- never delete or truncate the customer's decisions, their history or receipts. Deleting the publication
  -- or the account still cascades (referential actions run as the table owner, not as service_role).
  execute format('revoke delete,truncate on public.%I from service_role',t);
 end loop;
 for f in select p.oid::regprocedure signature,p.proname from pg_proc p join pg_namespace n on n.oid=p.pronamespace
  where n.nspname='public' and p.proname like 'pro_quote_line_%' loop
  execute format('revoke all on function %s from public,anon,authenticated',f.signature);
  if f.proname<>'pro_quote_line_decision_immutable' then execute format('grant execute on function %s to service_role',f.signature);end if;
 end loop;
end $$;
notify pgrst,'reload schema';
commit;

-- ===== vehicles-catalog-local.sql =====
-- ContrataCR Pro (LOCAL, no manifest yet): vehicle reference catalog.
-- Standalone: depends on no directory table. Read/written only by service_role.
-- Seed is a CURATED SEED, REVIEW before launch (from general knowledge of the Costa Rican market,
-- not an official registry; models/trim availability vary by year). Idempotent: apply any number of times.

create table if not exists public.ref_vehicle_makes (
  id bigint generated always as identity primary key,
  slug text not null unique check (slug ~ '^[a-z0-9]+(-[a-z0-9]+)*$'),
  name text not null check (length(btrim(name)) between 1 and 80),
  country_origin text check (country_origin is null or country_origin ~ '^[A-Z]{2}$'),
  vehicle_kinds text[] not null default '{}',
  active boolean not null default true,
  seed_status text not null default 'curated_seed_review' check (seed_status in ('curated_seed_review','reviewed')),
  created_at timestamptz not null default now()
);

create table if not exists public.ref_vehicle_models (
  id bigint generated always as identity primary key,
  make_id bigint not null references public.ref_vehicle_makes(id) on delete cascade,
  slug text not null check (slug ~ '^[a-z0-9]+(-[a-z0-9]+)*$'),
  name text not null check (length(btrim(name)) between 1 and 80),
  vehicle_type text not null check (vehicle_type in ('car','suv','pickup','van','truck','motorcycle','atv')),
  active boolean not null default true,
  seed_status text not null default 'curated_seed_review' check (seed_status in ('curated_seed_review','reviewed')),
  created_at timestamptz not null default now(),
  unique (make_id, slug)
);
create index if not exists ref_vehicle_models_type_idx on public.ref_vehicle_models (vehicle_type, make_id);

alter table public.ref_vehicle_makes enable row level security;
alter table public.ref_vehicle_models enable row level security;
revoke all on public.ref_vehicle_makes, public.ref_vehicle_models from public, anon, authenticated;
grant all on public.ref_vehicle_makes, public.ref_vehicle_models to service_role;
grant usage, select on sequence public.ref_vehicle_makes_id_seq, public.ref_vehicle_models_id_seq to service_role;

